/* ============================================================
   [CORE-001] [PROVIDERS: ALL] SHARED UTILITIES
   ============================================================ */

// [CORE-001.01] [PROVIDERS: ALL] SLUG NORMALIZATION
function toSlug(text) {
    if (!text) return "phim";

    return text
        .toString()
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/đ/g, "d")
        .replace(/[^a-z0-9\s]/g, "")
        .replace(/\s+/g, "-");
}

// [CORE-001.02] [PROVIDERS: ALL] MOVIE ID DECODING
function decodeMovieName(id) {
    try {
        const rawId = String(id || "");

        if (rawId.startsWith("vnwpsw:")) {
            return decodeURIComponent(
                rawId.substring("vnwpsw:".length)
            );
        }

        if (rawId.startsWith("tt")) {
            return "";
        }

        if (rawId.includes(":")) {
            return decodeURIComponent(
                rawId.split(":").slice(1).join(":")
            );
        }

        return decodeURIComponent(rawId);

    } catch (e) {
        return "";
    }
}


/* ============================================================
   [CORE-002] [PROVIDERS: ALL] POSTER URL HELPERS
   ============================================================ */

// [CORE-002.01] [PROVIDERS: ALL] POSTER URL RESOLUTION
function makePosterUrl(item) {
    if (!item) return undefined;

    const rawPoster =
        item.poster_url ||
        item.poster ||
        item.thumb_url ||
        item.thumb ||
        "";

    if (!rawPoster) return undefined;

    const poster = String(rawPoster).trim();

    if (
        poster.startsWith("https://") ||
        poster.startsWith("http://")
    ) {
        return poster;
    }

    if (poster.startsWith("//")) {
        return "https:" + poster;
    }

    const cleanPath = poster.startsWith("/")
        ? poster
        : "/" + poster;

    return "https://phimimg.com" + cleanPath;
}


/* ============================================================
[CORE-003] [PROVIDERS: ALL] CATALOG NORMALIZATION
============================================================ */

// [CORE-003.01] [PROVIDERS: ALL] CATALOG LIMIT
const CATALOG_TARGET = 50;

// [CORE-003.02] [PROVIDERS: ALL] CATALOG TEXT NORMALIZATION
function catalogNormalize(value) {

return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();

}

function catalogKey(item) {

return (
    item?.slug ||
    item?._id ||
    item?.id ||
    (
        String(item?.name || "") +
        "|" +
        String(item?.year || "")
    )
);

}

// [CORE-003.03] [PROVIDERS: ALL] CATALOG DEDUPLICATION
function catalogDedupe(items) {

const seen = new Set();
const result = [];

for (const item of items || []) {

    const key = catalogKey(item);

    if (!key || seen.has(key)) {
        continue;
    }

    seen.add(key);
    result.push(item);
}

return result;

}



/* ============================================================
   [CORE-003.04] [PROVIDERS: ALL] PHIMAPI REQUEST COORDINATOR
   FOREGROUND FIRST + BACKGROUND THROTTLING
   ============================================================ */

const MOVINA_PHIMAPI_MAX_CONCURRENT = 5;
const MOVINA_PHIMAPI_MIN_START_GAP = 80;
const MOVINA_PHIMAPI_DEFAULT_COOLDOWN = 6000;
const MOVINA_PHIMAPI_MAX_RETRY_AFTER = 30000;

const MOVINA_PHIMAPI_QUEUE = [];

let MOVINA_PHIMAPI_ACTIVE = 0;
let MOVINA_PHIMAPI_FOREGROUND_ACTIVE = 0;
let MOVINA_PHIMAPI_BACKGROUND_ACTIVE = 0;

let MOVINA_PHIMAPI_LAST_START = 0;
let MOVINA_PHIMAPI_COOLDOWN_UNTIL = 0;
let MOVINA_PHIMAPI_PUMP_TIMER = null;

function movinaPhimApiGet(
    url,
    config = {},
    retries = 1,
    priority = "foreground"
) {
    return new Promise((resolve, reject) => {
        MOVINA_PHIMAPI_QUEUE.push({
            url,
            config,
            retriesLeft: Math.max(0, Number(retries) || 0),
            priority:
                priority === "background"
                    ? "background"
                    : "foreground",
            resolve,
            reject
        });

        movinaPhimApiPump();
    });
}

function movinaPhimApiPump() {
    if (
        MOVINA_PHIMAPI_PUMP_TIMER ||
        MOVINA_PHIMAPI_ACTIVE >= MOVINA_PHIMAPI_MAX_CONCURRENT ||
        MOVINA_PHIMAPI_QUEUE.length === 0
    ) {
        return;
    }

    const foregroundIndex =
        MOVINA_PHIMAPI_QUEUE.findIndex(
            job => job.priority === "foreground"
        );

    let jobIndex = foregroundIndex;

    if (jobIndex < 0) {
        // Background chỉ được chạy khi không có
        // request foreground đang hoạt động.
        if (
            MOVINA_PHIMAPI_FOREGROUND_ACTIVE > 0 ||
            MOVINA_PHIMAPI_BACKGROUND_ACTIVE >= 1
        ) {
            return;
        }

        jobIndex =
            MOVINA_PHIMAPI_QUEUE.findIndex(
                job => job.priority === "background"
            );
    }

    if (jobIndex < 0) return;

    const now = Date.now();

    const waitUntil = Math.max(
        MOVINA_PHIMAPI_COOLDOWN_UNTIL,
        MOVINA_PHIMAPI_LAST_START +
            MOVINA_PHIMAPI_MIN_START_GAP
    );

    const waitMs = waitUntil - now;

    if (waitMs > 0) {
        MOVINA_PHIMAPI_PUMP_TIMER = setTimeout(() => {
            MOVINA_PHIMAPI_PUMP_TIMER = null;
            movinaPhimApiPump();
        }, waitMs);

        return;
    }

    const job =
        MOVINA_PHIMAPI_QUEUE.splice(jobIndex, 1)[0];

    if (!job) return;

    const isBackground =
        job.priority === "background";

    MOVINA_PHIMAPI_ACTIVE++;

    if (isBackground) {
        MOVINA_PHIMAPI_BACKGROUND_ACTIVE++;
    } else {
        MOVINA_PHIMAPI_FOREGROUND_ACTIVE++;
    }

    MOVINA_PHIMAPI_LAST_START = Date.now();

    axios.get(job.url, job.config)
        .then(response => {
            job.resolve(response);
        })
        .catch(error => {
            const status =
                Number(error?.response?.status || 0);

            if (status === 429) {
                const headers =
                    error?.response?.headers || {};

                const retryAfter =
                    headers["retry-after"] ||
                    headers["Retry-After"] ||
                    "";

                let cooldownMs =
                    MOVINA_PHIMAPI_DEFAULT_COOLDOWN;

                const retrySeconds =
                    Number(retryAfter);

                if (
                    Number.isFinite(retrySeconds) &&
                    retrySeconds > 0
                ) {
                    cooldownMs = retrySeconds * 1000;
                } else if (retryAfter) {
                    const retryDate =
                        Date.parse(retryAfter);

                    if (Number.isFinite(retryDate)) {
                        cooldownMs =
                            retryDate - Date.now();
                    }
                }

                cooldownMs = Math.max(
                    1000,
                    Math.min(
                        MOVINA_PHIMAPI_MAX_RETRY_AFTER,
                        cooldownMs
                    )
                );

                MOVINA_PHIMAPI_COOLDOWN_UNTIL =
                    Math.max(
                        MOVINA_PHIMAPI_COOLDOWN_UNTIL,
                        Date.now() + cooldownMs
                    );

                console.warn(
                    "[MOVINA PHIMAPI COOLDOWN]",
                    JSON.stringify({
                        priority: job.priority,
                        cooldownMs,
                        queued: MOVINA_PHIMAPI_QUEUE.length,
                        active: MOVINA_PHIMAPI_ACTIVE,
                        foregroundActive:
                            MOVINA_PHIMAPI_FOREGROUND_ACTIVE,
                        backgroundActive:
                            MOVINA_PHIMAPI_BACKGROUND_ACTIVE,
                        retry: job.retriesLeft > 0
                    })
                );

                if (job.retriesLeft > 0) {
                    job.retriesLeft--;

                    MOVINA_PHIMAPI_QUEUE.push(job);
                } else {
                    job.reject(error);
                }
            } else {
                job.reject(error);
            }
        })
        .finally(() => {
            MOVINA_PHIMAPI_ACTIVE--;

            if (isBackground) {
                MOVINA_PHIMAPI_BACKGROUND_ACTIVE--;
            } else {
                MOVINA_PHIMAPI_FOREGROUND_ACTIVE--;
            }

            movinaPhimApiPump();
        });

    // Ưu tiên cấp tiếp request foreground.
    movinaPhimApiPump();
}


/* ============================================================
   CATALOG FETCH CACHE
   ============================================================ */

const MOVINA_CATALOG_FETCH_CACHE = new Map();
const MOVINA_CATALOG_FETCH_TTL = 15 * 60 * 1000;
const MOVINA_CATALOG_FETCH_FAIL_TTL = 15 * 1000;

async function catalogFetch(url) {
    const cacheKey = String(url || "");
    const now = Date.now();
    const cached = MOVINA_CATALOG_FETCH_CACHE.get(cacheKey);

    if (cached && cached.expiresAt > now) {
        return cached.promise;
    }

    const requestPromise = (async () => {
        try {
            console.log("[CATALOG API] Request:", url);

            const response = await movinaPhimApiGet(
                url,
                {
                    timeout: 3000,
                    headers: {
                        "User-Agent": "Mozilla/5.0",
                        "Accept": "application/json"
                    }
                }
            );

            const items =
                response.data?.data?.items ??
                response.data?.items ??
                [];

            if (!Array.isArray(items)) {
                throw new Error("Invalid catalog response");
            }

            console.log("[CATALOG API] Items:", items.length);

            return items;
        } catch (error) {
            console.warn(
                "[CATALOG API ERROR]",
                url,
                error?.response?.status ||
                    error?.code ||
                    error?.message ||
                    "Unknown error"
            );

            return null;
        }
    })();

    MOVINA_CATALOG_FETCH_CACHE.set(cacheKey, {
        expiresAt: now + MOVINA_CATALOG_FETCH_TTL,
        promise: requestPromise
    });

    const items = await requestPromise;

    if (items === null) {
        MOVINA_CATALOG_FETCH_CACHE.set(cacheKey, {
            expiresAt: Date.now() + MOVINA_CATALOG_FETCH_FAIL_TTL,
            promise: Promise.resolve([])
        });

        return [];
    }

    return items;
}


// [CORE-003.05] [PROVIDERS: ALL] STABLE CATALOG HASH AND SHUFFLE

function stableHash(text) {

const str =
    String(text || "");

let hash = 2166136261;

for (let i = 0; i < str.length; i++) {

    hash ^= str.charCodeAt(i);

    hash =
        Math.imul(
            hash,
            16777619
        );
}

return hash >>> 0;

}

function stableShuffle(items, seed) {

return [...items]
    .sort(
        (a, b) =>
            stableHash(
                seed +
                "|" +
                catalogKey(a)
            ) -
            stableHash(
                seed +
                "|" +
                catalogKey(b)
            )
    );

}


/* ============================================================
   [CORE-004] [PROVIDERS: ALL] CATALOG POSTER HELPERS
   SMALL TMDB POSTER CACHE — PROGRESSIVE BACKGROUND
   ============================================================ */

const MOVINA_SMALL_POSTER_CACHE = new Map();
const MOVINA_SMALL_POSTER_INFLIGHT = new Map();

const MOVINA_SMALL_POSTER_TTL =
    30 * 24 * 60 * 60 * 1000;

const MOVINA_SMALL_POSTER_FAIL_TTL =
    12 * 60 * 60 * 1000;

const MOVINA_SMALL_POSTER_ERROR_TTL =
    30 * 60 * 1000;

const MOVINA_SMALL_POSTER_CACHE_MAX = 3000;

// Mỗi lượt chỉ xử lý tối đa 10 poster.
// Ưu tiên theo đúng thứ tự catalog.
const MOVINA_SMALL_POSTER_BACKGROUND_BATCH = 10;


function movinaSmallPosterCacheKey(item) {
    return String(item?.slug || "").trim();
}


function movinaSetSmallPosterCache(
    slug,
    url,
    ttl = MOVINA_SMALL_POSTER_TTL
) {
    if (!slug) return;

    if (
        !MOVINA_SMALL_POSTER_CACHE.has(slug) &&
        MOVINA_SMALL_POSTER_CACHE.size >=
            MOVINA_SMALL_POSTER_CACHE_MAX
    ) {
        const oldestKey =
            MOVINA_SMALL_POSTER_CACHE.keys().next().value;

        if (oldestKey) {
            MOVINA_SMALL_POSTER_CACHE.delete(oldestKey);
        }
    }

    MOVINA_SMALL_POSTER_CACHE.set(slug, {
        url: String(url || ""),
        expiresAt: Date.now() + ttl
    });
}


function movinaGetCachedSmallPoster(item) {
    const slug = movinaSmallPosterCacheKey(item);

    if (!slug) return "";

    const cached =
        MOVINA_SMALL_POSTER_CACHE.get(slug);

    if (!cached) return "";

    if (cached.expiresAt <= Date.now()) {
        MOVINA_SMALL_POSTER_CACHE.delete(slug);
        return "";
    }

    return cached.url || "";
}


function movinaHasSmallPosterCache(item) {
    const slug = movinaSmallPosterCacheKey(item);

    if (!slug) return false;

    const cached =
        MOVINA_SMALL_POSTER_CACHE.get(slug);

    if (!cached) return false;

    if (cached.expiresAt <= Date.now()) {
        MOVINA_SMALL_POSTER_CACHE.delete(slug);
        return false;
    }

    // Kể cả kết quả không tìm được ảnh cũng được cache
    // để tránh gọi API lặp đi lặp lại.
    return true;
}


function movinaIsSmallPosterUrl(url) {
    return /\/w(?:92|154|185|342)\//i.test(
        String(url || "")
    );
}


/*
 * Tìm poster TMDB kích thước w342.
 *
 * Chỉ lấy URL ảnh, không tải bytes ảnh về Vercel.
 * Trình duyệt Stremio sẽ tải ảnh trực tiếp từ TMDB.
 */
async function movinaFetchSmallPoster(item) {
    const slug = movinaSmallPosterCacheKey(item);

    if (!slug) return "";

    const cached =
        MOVINA_SMALL_POSTER_CACHE.get(slug);

    if (cached && cached.expiresAt > Date.now()) {
        return cached.url || "";
    }

    if (cached) {
        MOVINA_SMALL_POSTER_CACHE.delete(slug);
    }

    const inflight =
        MOVINA_SMALL_POSTER_INFLIGHT.get(slug);

    if (inflight) {
        return inflight;
    }

    const requestPromise = (async () => {
        try {
            const response = await movinaPhimApiGet(
                "https://phimapi.com/v1/api/phim/" +
                    encodeURIComponent(slug) +
                    "/images",
                {
                    timeout: 2500,
                    headers: {
                        "User-Agent": "Mozilla/5.0",
                        "Accept": "application/json"
                    }
                },
                0,
                "background"
            );

            const data =
                response.data?.data ||
                response.data ||
                {};

            const rawImages = data.images;

            let imageList = [];

            if (Array.isArray(rawImages)) {
                imageList = rawImages;
            } else if (
                Array.isArray(rawImages?.posters)
            ) {
                imageList = rawImages.posters;
            } else if (
                Array.isArray(rawImages?.poster)
            ) {
                imageList = rawImages.poster;
            }

            const posterCandidates =
                imageList.filter(image => {
                    const filePath =
                        image?.file_path ||
                        image?.poster_path ||
                        image?.path ||
                        "";

                    if (!filePath) return false;

                    const imageType = String(
                        image?.type ||
                        image?.image_type ||
                        image?.media_type ||
                        image?.category ||
                        ""
                    ).toLowerCase();

                    if (imageType.includes("poster")) {
                        return true;
                    }

                    if (imageType.includes("backdrop")) {
                        return false;
                    }

                    const width =
                        Number(image?.width || 0);

                    const height =
                        Number(image?.height || 0);

                    const aspectRatio =
                        Number(image?.aspect_ratio) ||
                        (
                            width > 0 && height > 0
                                ? width / height
                                : 0
                        );

                    // Poster thường có tỷ lệ dọc.
                    return (
                        aspectRatio > 0 &&
                        aspectRatio < 1.05
                    );
                });

            posterCandidates.sort(
                (a, b) =>
                    Number(b?.vote_average || 0) -
                    Number(a?.vote_average || 0)
            );

            const selectedPoster =
                posterCandidates[0];

            const filePath = String(
                selectedPoster?.file_path ||
                selectedPoster?.poster_path ||
                selectedPoster?.path ||
                ""
            ).trim();

            if (!filePath) {
                movinaSetSmallPosterCache(
                    slug,
                    "",
                    MOVINA_SMALL_POSTER_FAIL_TTL
                );

                return "";
            }

            const posterBase = String(
                data?.image_sizes?.poster?.w342 ||
                "https://image.tmdb.org/t/p/w342"
            ).replace(/\/+$/, "");

            let smallPosterUrl = "";

            if (/^https?:\/\//i.test(filePath)) {
                smallPosterUrl = filePath.replace(
                    /\/(?:original|w\d+)\//i,
                    "/w342/"
                );
            } else {
                smallPosterUrl =
                    posterBase +
                    "/" +
                    filePath.replace(/^\/+/, "");
            }

            if (!/^https?:\/\//i.test(smallPosterUrl)) {
                movinaSetSmallPosterCache(
                    slug,
                    "",
                    MOVINA_SMALL_POSTER_FAIL_TTL
                );

                return "";
            }

            movinaSetSmallPosterCache(
                slug,
                smallPosterUrl,
                MOVINA_SMALL_POSTER_TTL
            );

            return smallPosterUrl;

        } catch (error) {
            const status =
                Number(error?.response?.status || 0);

            console.warn(
                "[MOVINA SMALL POSTER ERROR]",
                slug,
                status || error?.code || error?.message
            );

            movinaSetSmallPosterCache(
                slug,
                "",
                MOVINA_SMALL_POSTER_ERROR_TTL
            );

            return "";

        } finally {
            MOVINA_SMALL_POSTER_INFLIGHT.delete(slug);
        }
    })();

    MOVINA_SMALL_POSTER_INFLIGHT.set(
        slug,
        requestPromise
    );

    return requestPromise;
}


// [CORE-004.01] [PROVIDERS: ALL] CATALOG POSTER RESOLUTION

function catalogPoster(item) {

    // 1. Dùng poster nhỏ đã có trong cache nếu còn hợp lệ.
    const cachedSmallPoster =
        movinaGetCachedSmallPoster(item);

    if (cachedSmallPoster) {
        return cachedSmallPoster;
    }

    // 2. Ưu tiên thumb_url vì đây thường là ảnh thumbnail.
    const raw =
        item?.thumb_url ||
        item?.thumb ||
        item?.poster_url ||
        item?.poster ||
        "";

    if (!raw) {
        return "";
    }

    const value = String(raw).trim();

    if (/^https?:\/\//i.test(value)) {
        return value;
    }

    if (value.startsWith("//")) {
        return "https:" + value;
    }

    if (value.startsWith("uploads/movies/")) {
        return "https://phimapi.com/" + value;
    }

    if (value.startsWith("upload/vod/")) {
        return "https://phimimg.com/" + value;
    }

    return "https://phimimg.com/" +
        value.replace(/^\/+/, "");
}

/* ============================================================
   [CORE-005] [PROVIDERS: ALL] MOVIE / SERIES CLASSIFICATION
   ============================================================ */

// ============================================================
// [CORE-005.02] [PROVIDERS: ALL] CATALOG COUNTRY AND CATEGORY CLASSIFICATION
// ============================================================

function catalogCountryNames(item) {

if (!Array.isArray(item?.country)) {
    return [];
}

return item.country
    .map(x =>
        typeof x === "string"
            ? x
            : x?.name
    )
    .filter(Boolean)
    .map(x => catalogNormalize(x));

}

function catalogCategoryNames(item) {

if (!Array.isArray(item?.category)) {
    return [];
}

return item.category
    .map(x =>
        typeof x === "string"
            ? x
            : x?.name
    )
    .filter(Boolean)
    .map(x => catalogNormalize(x));

}

function isHongKong(item) {

const countries =
    catalogCountryNames(item);

const text =
    catalogNormalize(
        [
            item?.name,
            item?.origin_name,
            item?.original_name
        ]
            .filter(Boolean)
            .join(" ")
    );

return (
    countries.some(x =>
        x.includes("hong kong") ||
        x.includes("hongkong")
    ) ||
    text.includes("hong kong") ||
    text.includes("hongkong") ||
    text.includes(" tvb ") ||
    text.startsWith("tvb ") ||
    text.endsWith(" tvb")
);

}


function isAnimation(item) {
    if (!item) {
        return false;
    }

    // Đánh dấu từ nguồn hoạt hình chuyên biệt.
    if (item.__isAnimation === true) {
        return true;
    }

    // Một số bản ghi dùng type thay vì category.
    const rawType = catalogNormalize(
        item?.type ||
        item?.type_name ||
        item?.typeName ||
        ""
    );

    if (
        rawType === "hoat hinh" ||
        rawType === "hoathinh" ||
        rawType === "animation" ||
        rawType === "anime"
    ) {
        return true;
    }

    const categories = catalogCategoryNames(item);

    return categories.some(category =>
        category === "hoat hinh" ||
        category === "hoathinh" ||
        category === "animation" ||
        category === "anime" ||
        category.includes("hoat hinh") ||
        category.includes("animation")
    );
}

function isJapanese(item) {

    const countries =
        catalogCountryNames(item);

    return countries.some(
        country =>
            country === "nhat ban" ||
            country === "japan"
    );
}

function isAmericanWestern(item) {

    const countries =
        catalogCountryNames(item);

    /*
       Nhóm Mỹ / Âu / phương Tây.

       Không dùng includes("my"), includes("anh")...
       vì có thể nhận nhầm tên quốc gia khác.

       PhimAPI thường dùng "Âu Mỹ" cho nhóm
       phim Mỹ / Âu.
    */

    const westernCountries = new Set([
        "au my",
        "my",
        "hoa ky",
        "united states",
        "united states of america",
        "usa",
        "anh",
        "vuong quoc anh",
        "united kingdom",
        "uk",
        "phap",
        "duc",
        "canada",
        "uc",
        "australia",
        "new zealand",
        "italia",
        "y",
        "tay ban nha",
        "tbn",
        "spain",
        "bo dao nha",
        "ireland",
        "tho nhi ky",
        "netherlands",
        "ha lan",
        "belgium",
        "bi",
        "sweden",
        "thuy dien",
        "norway",
        "na uy",
        "denmark",
        "phan lan",
        "finland",
        "switzerland",
        "ao",
        "austria"
    ]);

    return countries.some(
        country =>
            westernCountries.has(
                country
            )
    );
}

function isAsian(item) {

const countries =
    catalogCountryNames(item);

return countries.some(x =>
    x.includes("trung quoc") ||
    x.includes("han quoc") ||
    x.includes("nhat ban") ||
    x.includes("thai lan") ||
    x.includes("dai loan") ||
    x.includes("hong kong") ||
    x.includes("an do") ||
    x.includes("philippines") ||
    x.includes("indonesia")
);

}

// [CORE-005.01] [PROVIDERS: ALL] MOVIE / SERIES DETECTION
function isSeriesItem(item) {

    if (!item) {
        return false;
    }

    /*
       ========================================================
       5.1. TYPE NỘI BỘ DO CHÚNG TA GÁN
       ========================================================
    */

    if (
        item.__catalogType ===
        "series"
    ) {
        return true;
    }

    if (
        item.__catalogType ===
        "movie"
    ) {
        return false;
    }

    /*
       ========================================================
       5.2. TYPE CỦA PHIMAPI
       ========================================================
    */

    const rawType =
        String(
            item?.type ||
            ""
        )
            .trim()
            .toLowerCase();

    if (
        rawType === "series" ||
        rawType === "tvshows" ||
        rawType === "tvshow"
    ) {
        return true;
    }

    if (
        rawType === "single" ||
        rawType === "movie"
    ) {
        return false;
    }

    /*
       "hoathinh" chỉ cho biết đây là hoạt hình,
       KHÔNG tự nó cho biết movie hay series.
    */

    /*
       ========================================================
       5.3. TMDB TYPE
       ========================================================
    */

    const tmdbType =
        String(
            item?.tmdb?.type ||
            ""
        )
            .trim()
            .toLowerCase();

    if (
        tmdbType === "tv" ||
        tmdbType === "series"
    ) {
        return true;
    }

    if (
        tmdbType === "movie"
    ) {
        return false;
    }

    /*
       ========================================================
       5.4. DẤU HIỆU PHỤ TỪ SỐ TẬP
       ========================================================
    */

    const episodeCurrent =
        String(
            item?.episode_current ||
            ""
        )
            .trim()
            .toLowerCase();

    const episodeTotal =
        String(
            item?.episode_total ||
            ""
        )
            .trim()
            .toLowerCase();

    const looksLikeSeries =
        (
            episodeTotal &&
            episodeTotal !== "1" &&
            episodeTotal !== "full"
        ) ||
        (
            episodeCurrent &&
            episodeCurrent !== "full" &&
            /\d/.test(
                episodeCurrent
            )
        );

    if (
        looksLikeSeries
    ) {
        return true;
    }

    /*
       Không đủ bằng chứng
       => movie.
    */

    return false;
}

// [CORE-005.02] [PROVIDERS: ALL] RELEASE YEAR AND DECADE HELPERS

function itemYear(item) {

const y =
    Number(
        item?.year ||
        item?.release_year ||
        item?.tmdb?.release_date?.slice?.(0, 4) ||
        0
    );

return Number.isFinite(y)
    ? y
    : 0;

}

function decadeOf(item) {

const year =
    itemYear(item);

if (!year) {
    return null;
}

return Math.floor(year / 10) * 10;

}


/* ============================================================
[CORE-006] [PROVIDERS: ALL] MOVIE TRENDING CATALOG
============================================================ */

// [CORE-006.01] [PROVIDERS: ALL] MOVIE TRENDING FETCH
async function fetchMovieTrending() {

    const pages = [];

    /*
       Lấy nhiều trang phim chiếu rạp
       để có đủ dữ liệu mới nhất.
    */

    for (
        let page = 1;
        page <= 6;
        page++
    ) {

        pages.push(
            catalogFetch(
                "https://phimapi.com/v1/api/" +
                "danh-sach/phim-chieu-rap" +
                "?page=" +
                page +
                "&limit=24"
            )
        );
    }

    const groups =
        await Promise.all(
            pages
        );

    let items =
        catalogDedupe(
            groups.flat()
        );

    /*
       Chỉ lấy phim lẻ.
    */

    items =
        items.filter(
            item =>
                !isSeriesItem(item)
        );

    /*
       Ưu tiên phim mới:
       1. Năm phát hành mới hơn
       2. Ngày cập nhật mới hơn
    */

    items =
        items.sort(
            (a, b) => {

                const yearA =
                    itemYear(a);

                const yearB =
                    itemYear(b);

                if (
                    yearB !==
                    yearA
                ) {
                    return (
                        yearB -
                        yearA
                    );
                }

                const modifiedA =
                    Date.parse(
                        a?.modified?.time ||
                        ""
                    ) || 0;

                const modifiedB =
                    Date.parse(
                        b?.modified?.time ||
                        ""
                    ) || 0;

                return (
                    modifiedB -
                    modifiedA
                );
            }
        );

    return items.slice(
        0,
        CATALOG_TARGET
    );

}

/* ============================================================
[CORE-007] [PROVIDERS: ALL] SERIES TRENDING CATALOG
============================================================ */

/*
   phim-bo-dang-chieu KHÔNG tồn tại ở endpoint hiện tại.

   Dùng phim-bo + year/modified để ưu tiên
   các phim bộ mới nhất.
*/

// [CORE-007.01] [PROVIDERS: ALL] SERIES TRENDING FETCH
async function fetchSeriesTrending() {

    const pages = [];

    /*
       Lấy nhiều trang hơn để có đủ dữ liệu
       trước khi chọn 50 phim bộ.
    */

    for (
        let page = 1;
        page <= 6;
        page++
    ) {

        pages.push(
            catalogFetch(
                "https://phimapi.com/v1/api/" +
                "danh-sach/phim-bo" +
                "?page=" +
                page +
                "&limit=24"
            )
        );
    }

    const groups =
        await Promise.all(
            pages
        );

    let items =
        catalogDedupe(
            groups.flat()
        );

    /*
       Chỉ giữ phim bộ.
    */

    items =
        items.filter(
            item =>
                isSeriesItem(item)
        );

    /*
       Ưu tiên phim mới:
       1. Năm phát hành mới hơn
       2. Ngày cập nhật mới hơn
    */

    items =
        items.sort(
            (a, b) => {

                const yearA =
                    itemYear(a);

                const yearB =
                    itemYear(b);

                if (
                    yearB !==
                    yearA
                ) {
                    return (
                        yearB -
                        yearA
                    );
                }

                const modifiedA =
                    Date.parse(
                        a?.modified?.time ||
                        ""
                    ) || 0;

                const modifiedB =
                    Date.parse(
                        b?.modified?.time ||
                        ""
                    ) || 0;

                return (
                    modifiedB -
                    modifiedA
                );
            }
        );

    return items.slice(
        0,
        CATALOG_TARGET
    );

}



/* ============================================================
   [CORE-006.02] MOVINA TRENDING GENRE FILTER
   [CORE-007.02] MOVINA DAILY DECADE SELECTION
   ============================================================ */
 


// MOVINA — CLASSIC IMDb LOADER
// Chỉ dùng điểm IMDb thật, không dùng TMDB thay thế.

function movinaTrendingIMDb(item) {
    const values = [
        item?.__movinaIMDbRating,
        item?.imdb?.vote_average,
        item?.imdb?.rating,
        item?.imdb_rating,
        item?.imdbRating,
        item?.imdb?.score
    ];

    for (const raw of values) {
        if (
            raw === null ||
            raw === undefined ||
            raw === ""
        ) {
            continue;
        }

        const rating = Number(raw);

        if (
            Number.isFinite(rating) &&
            rating > 0 &&
            rating <= 10
        ) {
            return rating;
        }
    }

    return 0;
}

const MOVINA_TRENDING_IMDB_CACHE = new Map();



/* ============================================================
   MOVINA — CLASSIC IMDb BULK LOADER
   Không tra cứu riêng từng phim.
   Lấy danh sách IMDb 8+, đối chiếu tên + năm, cache theo loại.
   ============================================================ */

const MOVINA_CLASSIC_IMDB_BULK_CACHE = new Map();

async function movinaTrendingLoadIMDb(items) {
    const result = [...(items || [])];

    if (!result.length) {
        return result;
    }

    const CACHE_TTL = 6 * 60 * 60 * 1000;
    const PAGE_SIZE = 50;
    const MAX_PAGES_PER_LOAD = 8;
    const MIN_VOTES = 500;
    const TIMEOUT_MS = 4500;
    const TARGET = 50;

    const isSeries = result.some(item =>
        item?.__catalogType === "series" ||
        isSeriesItem(item)
    );

    const cacheKey = isSeries ? "series" : "movie";

    function normalizeTitle(value) {
        return String(value || "")
            .toLowerCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/đ/g, "d")
            .replace(/[^\p{L}\p{N}]+/gu, " ")
            .replace(/\s+/g, " ")
            .trim();
    }

    function ratingOf(title) {
        const rating = Number(
            title?.rating?.aggregateRating ??
            title?.rating?.aggregate_rating ??
            title?.rating?.averageRating ??
            title?.aggregateRating ??
            0
        );

        const votes = Number(
            title?.rating?.voteCount ??
            title?.rating?.votes_count ??
            title?.rating?.vote_count ??
            0
        );

        if (
            Number.isFinite(rating) &&
            rating >= 8.0 &&
            rating <= 10 &&
            votes >= MIN_VOTES
        ) {
            return rating;
        }

        return 0;
    }

    function titleNames(item) {
        return [
            item?.origin_name,
            item?.original_name,
            item?.name,
            item?.title
        ]
            .map(normalizeTitle)
            .filter(Boolean);
    }

    function yearOf(item) {
        return itemYear(item) || 0;
    }

    function findRating(item, imdbTitles) {
        const names = titleNames(item);

        if (!names.length) {
            return 0;
        }

        const year = yearOf(item);
        let best = null;

        for (const title of imdbTitles) {
            const rating = ratingOf(title);

            if (!rating) {
                continue;
            }

            const imdbNames = [
                title?.primaryTitle,
                title?.originalTitle,
                title?.primary_title,
                title?.original_title
            ]
                .map(normalizeTitle)
                .filter(Boolean);

            if (!imdbNames.some(name => names.includes(name))) {
                continue;
            }

            const imdbYear = Number(
                title?.startYear ??
                title?.start_year ??
                0
            ) || 0;

            if (
                year &&
                imdbYear &&
                Math.abs(year - imdbYear) > 1
            ) {
                continue;
            }

            const difference =
                year && imdbYear
                    ? Math.abs(year - imdbYear)
                    : 99;

            if (
                !best ||
                difference < best.yearDifference
            ) {
                best = {
                    rating,
                    yearDifference: difference
                };
            }
        }

        return best?.rating || 0;
    }

    let cache = MOVINA_CLASSIC_IMDB_BULK_CACHE.get(cacheKey);

    if (
        !cache ||
        Date.now() - cache.updatedAt > CACHE_TTL
    ) {
        cache = {
            titles: [],
            nextPageToken: "",
            exhausted: false,
            updatedAt: Date.now()
        };

        MOVINA_CLASSIC_IMDB_BULK_CACHE.set(
            cacheKey,
            cache
        );
    }

    let pagesFetched = 0;
    let apiErrors = 0;

    function countMatched() {
        return result.filter(item =>
            movinaTrendingIMDb(item) >= 8.0 ||
            findRating(item, cache.titles) >= 8.0
        ).length;
    }

    while (
        countMatched() < TARGET &&
        pagesFetched < MAX_PAGES_PER_LOAD &&
        !cache.exhausted
    ) {
        try {
            const params = new URLSearchParams();

            if (isSeries) {
                params.append("types", "TV_SERIES");
                params.append("types", "TV_MINI_SERIES");
            } else {
                params.append("types", "MOVIE");
            }

            params.set("minAggregateRating", "8");
            params.set("minVoteCount", String(MIN_VOTES));
            params.set("sortBy", "SORT_BY_USER_RATING_COUNT");
            params.set("sortOrder", "DESC");
            params.set("limit", String(PAGE_SIZE));

            if (cache.nextPageToken) {
                params.set("pageToken", cache.nextPageToken);
            }

            const response = await axios.get(
                "https://api.imdbapi.dev/titles",
                {
                    params,
                    timeout: TIMEOUT_MS,
                    headers: {
                        "Accept": "application/json",
                        "User-Agent": "MOVINA/1.0"
                    }
                }
            );

            const payload = response.data || {};

            const titles = Array.isArray(payload.titles)
                ? payload.titles
                : Array.isArray(payload.results)
                    ? payload.results
                    : [];

            const seenIds = new Set(
                cache.titles.map(title => title?.id).filter(Boolean)
            );

            for (const title of titles) {
                const id = String(title?.id || "");

                if (!id || !seenIds.has(id)) {
                    cache.titles.push(title);

                    if (id) {
                        seenIds.add(id);
                    }
                }
            }

            cache.nextPageToken =
                payload.nextPageToken ||
                payload.next_page_token ||
                "";

            cache.exhausted = !cache.nextPageToken;
            cache.updatedAt = Date.now();
            pagesFetched++;
        } catch (error) {
            apiErrors++;

            console.warn(
                "[MOVINA IMDb BULK ERROR]",
                cacheKey,
                error?.response?.status ||
                    error?.message ||
                    error
            );

            // Không lặp vô hạn nếu API đang lỗi.
            break;
        }
    }

    
    let matched = 0;
    let alreadyRated = 0;
    let directMatched = 0;
    let fallbackErrors = 0;
    let directIdCandidates = 0;

    /*
     * FALLBACK 1:
     * Lấy điểm IMDb theo IMDb ID, không phụ thuộc vào tên phim.
     *
     * API tài liệu:
     * https://agregarr.org/docs/imdb-ratings/
     *
     * Tối đa 100 IMDb ID / request.
     */

    if (!(cache.directRatings instanceof Map)) {
        cache.directRatings = new Map();
    }

    function imdbIdOf(item) {
        const candidates = [
            item?.imdb?.id,
            item?.imdb_id,
            item?.imdbId,
            item?.imdb?.imdb_id
        ];

        for (const value of candidates) {
            const id = String(value || "").trim();

            if (/^tt\d+$/i.test(id)) {
                return id;
            }
        }

        return "";
    }

    // Đếm những phim đã có điểm IMDb hợp lệ trước fallback.
    alreadyRated = result.filter(item =>
        movinaTrendingIMDb(item) >= 8.0
    ).length;

    const idToItems = new Map();

    for (const item of result) {
        // Chỉ tra cứu khi chưa có điểm IMDb.
        if (movinaTrendingIMDb(item) > 0) {
            continue;
        }

        const imdbId = imdbIdOf(item);

        if (!imdbId) {
            continue;
        }

        if (!idToItems.has(imdbId)) {
            idToItems.set(imdbId, []);
        }

        idToItems.get(imdbId).push(item);
    }

    directIdCandidates = idToItems.size;

    const missingIds = [...idToItems.keys()].filter(
        id => !cache.directRatings.has(id)
    );

    // API cho phép tối đa 100 ID mỗi request.
    const batches = [];

    for (let i = 0; i < missingIds.length; i += 100) {
        batches.push(missingIds.slice(i, i + 100));
    }

    // Chạy tối đa 4 batch đồng thời để tránh gây tải quá lớn.
    for (let i = 0; i < batches.length; i += 4) {
        const group = batches.slice(i, i + 4);

        const responses = await Promise.all(
            group.map(async ids => {
                try {
                    const params = new URLSearchParams();

                    for (const id of ids) {
                        params.append("id", id);
                    }

                    const response = await axios.get(
                        "https://api.agregarr.org/api/ratings?" +
                            params.toString(),
                        {
                            timeout: TIMEOUT_MS,
                            headers: {
                                "Accept": "application/json",
                                "User-Agent": "MOVINA/1.0"
                            }
                        }
                    );

                    const rows = Array.isArray(response.data)
                        ? response.data
                        : Array.isArray(response.data?.ratings)
                            ? response.data.ratings
                            : [];

                    return { rows, requested: ids, error: false };

                } catch (error) {
                    fallbackErrors++;

                    console.warn(
                        "[MOVINA IMDb ID FALLBACK ERROR]",
                        error?.response?.status ||
                            error?.message ||
                            error
                    );

                    return {
                        rows: [],
                        requested: ids,
                        error: true
                    };
                }
            })
        );

        for (const batch of responses) {
            if (batch.error) {
                continue;
            }

            const returnedIds = new Set();

            for (const row of batch.rows) {
                const imdbId = String(
                    row?.imdbId ||
                    row?.imdb_id ||
                    row?.id ||
                    ""
                ).trim();

                if (!/^tt\d+$/i.test(imdbId)) {
                    continue;
                }

                const rawRating = row?.rating;
                const rating =
                    rawRating === null ||
                    rawRating === undefined ||
                    rawRating === ""
                        ? 0
                        : Number(rawRating);

                if (
                    Number.isFinite(rating) &&
                    rating > 0 &&
                    rating <= 10
                ) {
                    cache.directRatings.set(imdbId, rating);
                    returnedIds.add(imdbId);
                } else {
                    cache.directRatings.set(imdbId, 0);
                    returnedIds.add(imdbId);
                }
            }

            // Những ID API không trả về được đánh dấu chưa có điểm.
            // Không giả định chúng đạt 8.0.
            for (const id of batch.requested) {
                if (!returnedIds.has(id)) {
                    cache.directRatings.set(id, 0);
                }
            }
        }
    }

    // Gắn điểm đã xác minh theo IMDb ID vào ứng viên.
    for (let index = 0; index < result.length; index++) {
        const item = result[index];

        if (movinaTrendingIMDb(item) > 0) {
            continue;
        }

        const imdbId = imdbIdOf(item);

        if (!imdbId || !cache.directRatings.has(imdbId)) {
            continue;
        }

        const rating = Number(
            cache.directRatings.get(imdbId) || 0
        );

        if (
            Number.isFinite(rating) &&
            rating > 0 &&
            rating <= 10
        ) {
            result[index] = {
                ...item,
                __movinaIMDbRating: rating
            };

            if (rating >= 8.0) {
                directMatched++;
            }
        }
    }

    /*
     * FALLBACK 2:
     * Tiếp tục ghép tên + năm từ danh sách bulk nếu có.
     * Không ghi đè điểm đã lấy theo IMDb ID.
     */

    for (let index = 0; index < result.length; index++) {
        const item = result[index];
        const existingRating = movinaTrendingIMDb(item);

        if (existingRating > 0) {
            continue;
        }

        const rating = findRating(item, cache.titles);

        if (rating >= 8.0) {
            result[index] = {
                ...item,
                __movinaIMDbRating: rating
            };

            if (item?.slug) {
                MOVINA_TRENDING_IMDB_CACHE.set(
                    String(item.slug),
                    rating
                );
            }

            matched++;
        }
    }

    console.log(
        "[MOVINA CLASSIC BULK SUMMARY]",
        JSON.stringify({
            type: cacheKey,
            input: result.length,
            imdbTitlesCached: cache.titles.length,
            pagesFetched,
            alreadyRated,
            matched,
            qualified: result.filter(item =>
                movinaTrendingIMDb(item) >= 8.0
            ).length,
            hasNextPage: !cache.exhausted,
            apiErrors
        })
    );

    return result;
}


/* ============================================================
 * MOVINA — TMDB FALLBACK FOR CLASSIC CATALOG
 *
 * IMDb luôn được ưu tiên.
 * TMDB chỉ dùng khi ứng viên chưa có điểm IMDb.
 * TMDB score vẫn được lưu riêng, không giả làm IMDb.
 *
 * Vercel Environment Variable:
 * TMDB_READ_ACCESS_TOKEN = TMDB API Read Access Token
 * ============================================================ */

const MOVINA_CLASSIC_TMDB_CACHE = new Map();


function movinaTrendingTMDB(item) {
    const ratingValues = [
        item?.__movinaTMDBRating,
        item?.tmdb?.vote_average,
        item?.tmdb?.rating,
        item?.tmdb_rating,
        item?.tmdbRating
    ];

    let rating = 0;

    for (const raw of ratingValues) {
        if (raw === null || raw === undefined || raw === "") {
            continue;
        }

        const value = Number(raw);

        if (Number.isFinite(value) && value > 0 && value <= 10) {
            rating = value;
            break;
        }
    }

    if (rating < 8.0) {
        return 0;
    }

    const voteValues = [
        item?.__movinaTMDBVotes,
        item?.tmdb?.vote_count,
        item?.tmdb?.voteCount,
        item?.tmdb_vote_count,
        item?.tmdbVoteCount
    ];

    let votes = 0;

    for (const raw of voteValues) {
        if (raw === null || raw === undefined || raw === "") {
            continue;
        }

        const value = Number(raw);

        if (Number.isFinite(value) && value >= 0) {
            votes = value;
            break;
        }
    }

    // Chỉ dùng điểm TMDB khi metadata có thông tin vote
    // và đạt ngưỡng tối thiểu 100 lượt bình chọn.
    return votes >= 100 ? rating : 0;
}


async function movinaTrendingLoadTMDB(items, contentType) {
    const result = [...(items || [])];

    if (!result.length) {
        return result;
    }

    const type = contentType === "series" ? "series" : "movie";
    const CACHE_TTL = 6 * 60 * 60 * 1000;
    const MAX_PAGES = 8;
    const MIN_VOTES = 500;
    const TIMEOUT_MS = 6000;

    const token = String(
        process.env.TMDB_READ_ACCESS_TOKEN || ""
    ).trim();

    const apiKey = String(
        process.env.TMDB_API_KEY || ""
    ).trim();

    function normalizeTitle(value) {
        return String(value || "")
            .toLowerCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/đ/g, "d")
            .replace(/[^\p{L}\p{N}]+/gu, " ")
            .replace(/\s+/g, " ")
            .trim();
    }

    function itemNames(item) {
        return [
            item?.origin_name,
            item?.original_name,
            item?.name,
            item?.title
        ].map(normalizeTitle).filter(Boolean);
    }

    function itemYearValue(item) {
        return Number(itemYear(item) || 0);
    }

    function tmdbTitleNames(row) {
        return [
            row?.title,
            row?.original_title,
            row?.name,
            row?.original_name
        ].map(normalizeTitle).filter(Boolean);
    }

    function tmdbYearValue(row) {
        const date = String(
            type === "series"
                ? row?.first_air_date || ""
                : row?.release_date || ""
        );

        const parsed = Number(date.slice(0, 4));
        return Number.isFinite(parsed) ? parsed : 0;
    }

    let cache = MOVINA_CLASSIC_TMDB_CACHE.get(type);

    if (
        !cache ||
        Date.now() - cache.updatedAt > CACHE_TTL
    ) {
        cache = {
            rows: [],
            updatedAt: 0,
            error: false
        };

        if (!token && !apiKey) {
            console.warn(
                "[MOVINA TMDB FALLBACK]",
                "Missing TMDB_READ_ACCESS_TOKEN / TMDB_API_KEY"
            );
            cache.error = true;
        } else {
            const rowsById = new Map();

            for (let page = 1; page <= MAX_PAGES; page++) {
                try {
                    const params = {
                        page,
                        sort_by: "vote_count.desc",
                        "vote_average.gte": 8.0,
                        "vote_count.gte": MIN_VOTES,
                        include_adult: false
                    };

                    if (!token && apiKey) {
                        params.api_key = apiKey;
                    }

                    const endpoint =
                        type === "series"
                            ? "https://api.themoviedb.org/3/discover/tv"
                            : "https://api.themoviedb.org/3/discover/movie";

                    const response = await axios.get(endpoint, {
                        params,
                        timeout: TIMEOUT_MS,
                        headers: {
                            Accept: "application/json",
                            ...(token
                                ? { Authorization: "Bearer " + token }
                                : {})
                        }
                    });

                    const rows = Array.isArray(response.data?.results)
                        ? response.data.results
                        : [];

                    for (const row of rows) {
                        const id = String(row?.id || "");
                        if (id) rowsById.set(id, row);
                    }

                    const totalPages = Number(
                        response.data?.total_pages || page
                    );

                    if (page >= totalPages || !rows.length) {
                        break;
                    }
                } catch (error) {
                    cache.error = true;

                    console.warn(
                        "[MOVINA TMDB API ERROR]",
                        type,
                        error?.response?.status ||
                            error?.message ||
                            error
                    );

                    break;
                }
            }

            cache.rows = [...rowsById.values()];
            cache.updatedAt = Date.now();
            MOVINA_CLASSIC_TMDB_CACHE.set(type, cache);
        }

        if (!cache.updatedAt) {
            cache.updatedAt = Date.now();
            MOVINA_CLASSIC_TMDB_CACHE.set(type, cache);
        }
    }

    let matched = 0;

    for (let index = 0; index < result.length; index++) {
        const item = result[index];

        // Không thay thế điểm IMDb đã có bằng điểm TMDB.
        if (movinaTrendingIMDb(item) > 0) {
            continue;
        }

        // Nếu metadata nguồn đã có TMDB rating hợp lệ thì giữ lại.
        if (movinaTrendingTMDB(item) >= 8.0) {
            continue;
        }

        const names = itemNames(item);
        if (!names.length) continue;

        const year = itemYearValue(item);
        let best = null;

        for (const row of cache.rows || []) {
            const rating = Number(row?.vote_average || 0);
            const votes = Number(row?.vote_count || 0);

            if (
                !Number.isFinite(rating) ||
                rating < 8.0 ||
                rating > 10 ||
                votes < MIN_VOTES
            ) {
                continue;
            }

            const namesFromTMDB = tmdbTitleNames(row);

            // Chỉ khớp tên chính xác đã chuẩn hóa, không khớp gần đúng.
            if (!namesFromTMDB.some(name => names.includes(name))) {
                continue;
            }

            const tmdbYear = tmdbYearValue(row);

            if (
                year &&
                tmdbYear &&
                Math.abs(year - tmdbYear) > 1
            ) {
                continue;
            }

            const yearDifference =
                year && tmdbYear ? Math.abs(year - tmdbYear) : 99;

            if (
                !best ||
                yearDifference < best.yearDifference ||
                (
                    yearDifference === best.yearDifference &&
                    votes > best.votes
                )
            ) {
                best = {
                    rating,
                    votes,
                    yearDifference
                };
            }
        }

        if (best) {
            result[index] = {
                ...item,
                __movinaTMDBRating: best.rating,
                __movinaTMDBVotes: best.votes,
                __movinaRatingSource: "TMDB"
            };

            matched++;
        }
    }

    console.log(
        "[MOVINA TMDB FALLBACK SUMMARY]",
        JSON.stringify({
            type,
            input: result.length,
            tmdbRowsCached: (cache.rows || []).length,
            matched,
            qualifiedTMDB: result.filter(item =>
                movinaTrendingIMDb(item) === 0 &&
                movinaTrendingTMDB(item) >= 8.0
            ).length,
            apiError: !!cache.error
        })
    );

    return result;
}



/* ============================================================
   [CLASSIC-001] [MOVINA] IMDb TOP 250 JSON + PHIMAPI MATCH
   - Movie và series có danh sách độc lập.
   - Đọc JSON, không scrape HTML IMDb/ListChallenges.
   - Ưu tiên đối chiếu IMDb ID, sau đó mới tên chính xác.
   - Không bổ sung phim ngoài danh sách xếp hạng.
   ============================================================ */

const MOVINA_CLASSIC_RANKED_CACHE = new Map();
const MOVINA_CLASSIC_SEARCH_CACHE = new Map();

const MOVINA_CLASSIC_RANKED_SOURCES = {
    movie: [
        "https://raw.githubusercontent.com/crazyuploader/IMDb-Top-50/main/data/top250/movies.json",
        "https://raw.githubusercontent.com/sharmadhiraj/free-json-datasets/master/docs/sports-entertainment/imdb_top_movies.json"
    ],
    series: [
        "https://raw.githubusercontent.com/crazyuploader/IMDb-Top-50/main/data/top250/shows.json",
        "https://gist.githubusercontent.com/johnhamm/c200ec34e974b6842e17ced8fe8ffbb1/raw/imdbtop250tvshows.json"
    ]
};

function movinaClassicNormalize(value) {
    return String(value || "")
        .replace(/&apos;|&#0*39;/gi, "'")
        .replace(/&quot;/gi, '"')
        .replace(/&amp;/gi, "&")
        .replace(/&nbsp;/gi, " ")
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/đ/g, "d")
        .replace(/[^\p{L}\p{N}]+/gu, " ")
        .replace(/\s+/g, " ")
        .trim();
}

function movinaClassicIMDbId(value) {
    const text = String(value || "").trim();
    const match = text.match(/tt\d+/i);
    return match ? match[0].toLowerCase() : "";
}

function movinaClassicItemIMDbId(item) {
    const values = [
        item?.imdb?.id,
        item?.imdb_id,
        item?.imdbId,
        item?.imdb?.imdb_id,
        item?.__movinaClassicImdbId
    ];

    for (const value of values) {
        const id = movinaClassicIMDbId(value);
        if (id) return id;
    }

    return "";
}

function movinaClassicParseRankedPayload(payload) {
    let data = payload;

    if (typeof data === "string") {
        try {
            data = JSON.parse(data);
        } catch {
            return [];
        }
    }

    let entries = Array.isArray(data)
        ? data
        : Array.isArray(data?.data)
            ? data.data
            : Array.isArray(data?.top250movies)
                ? data.top250movies
                : Array.isArray(data?.items)
                    ? data.items
                    : [];

    return entries
        .map((entry, index) => {
            const title = String(
                entry?.name ||
                entry?.title ||
                entry?.primaryTitle ||
                entry?.primary_title ||
                ""
            )
                .replace(/&apos;|&#0*39;/gi, "'")
                .replace(/&quot;/gi, '"')
                .replace(/&amp;/gi, "&")
                .trim();

            const imdbId = movinaClassicIMDbId(
                entry?.link ||
                entry?.url ||
                entry?.imdbId ||
                entry?.imdb_id ||
                entry?.id
            );

            const rank = Number(
                entry?.Rank ||
                entry?.rank ||
                index + 1
            );

            const rating = Number(
                entry?.["IMDb Rating"] ??
                entry?.rating ??
                entry?.imDbRating ??
                entry?.imdbRating ??
                0
            );

            const year = Number(
                entry?.year ||
                entry?.releaseYear ||
                entry?.startYear ||
                0
            ) || 0;

            if (!title || !Number.isFinite(rank)) {
                return null;
            }

            return {
                title,
                imdbId,
                rank,
                rating:
                    Number.isFinite(rating) &&
                    rating > 0 &&
                    rating <= 10
                        ? rating
                        : 0,
                year
            };
        })
        .filter(Boolean)
        .sort((a, b) => a.rank - b.rank)
        .slice(0, 250);
}

async function movinaClassicGetRankedTitles(type) {
    const key = type === "series" ? "series" : "movie";
    const TTL = 6 * 60 * 60 * 1000;

    const cached = MOVINA_CLASSIC_RANKED_CACHE.get(key);

    if (cached && Date.now() - cached.time < TTL) {
        return cached.rows;
    }

    const urls = MOVINA_CLASSIC_RANKED_SOURCES[key] || [];

    for (const url of urls) {
        try {
            const response = await axios.get(url, {
                timeout: 8000,
                headers: {
                    "User-Agent": "MOVINA/1.0",
                    "Accept": "application/json, text/plain, */*"
                }
            });

            const rows = movinaClassicParseRankedPayload(
                response.data
            );

            // Không chấp nhận JSON lỗi hoặc danh sách bị cắt cụt.
            if (rows.length < 100) {
                console.warn(
                    "[MOVINA CLASSIC JSON INCOMPLETE]",
                    key,
                    JSON.stringify({
                        url,
                        rows: rows.length
                    })
                );
                continue;
            }

            console.log(
                "[MOVINA CLASSIC LIST]",
                JSON.stringify({
                    type: key,
                    source: url,
                    rows: rows.length,
                    firstTitle: rows[0]?.title || "",
                    lastRank: rows[rows.length - 1]?.rank || 0
                })
            );

            MOVINA_CLASSIC_RANKED_CACHE.set(key, {
                time: Date.now(),
                rows
            });

            return rows;

        } catch (error) {
            console.warn(
                "[MOVINA CLASSIC JSON ERROR]",
                key,
                url,
                error?.response?.status || error?.message
            );
        }
    }

    // Cache lỗi ngắn hạn để tránh gọi lại liên tục khi nguồn hỏng.
    MOVINA_CLASSIC_RANKED_CACHE.set(key, {
        time: Date.now() - TTL + 10 * 60 * 1000,
        rows: []
    });

    console.error(
        "[MOVINA CLASSIC NO RANKED LIST]",
        key
    );

    return [];
}


function movinaClassicFindExactMatch(title, items) {
    const expectedName = movinaClassicNormalize(title?.title);

    if (!expectedName) return null;

    // Nhận diện tên gốc có hậu tố mùa:
    // "Breaking Bad (Season 1)" -> "breaking bad"
    // "Tập làm người xấu (Phần 1)" -> "tap lam nguoi xau"
    const normalizeSeriesBaseName = value =>
        movinaClassicNormalize(value)
            .replace(/\s+(?:season|phan|part)\s+\d+\s*$/i, "")
            .trim();

    const getSeasonNumber = item => {
        const names = [
            item?.origin_name,
            item?.original_name,
            item?.name,
            item?.title
        ];

        for (const value of names) {
            const normalized = movinaClassicNormalize(value);
            const match = normalized.match(
                /(?:^|\s)(?:season|phan|part)\s+(\d+)\s*$/
            );

            if (match) return Number(match[1]);
        }

        return 0;
    };

    const exactCandidates = (items || []).filter(item => {
        const names = [
            item?.origin_name,
            item?.original_name,
            item?.name,
            item?.title
        ]
            .map(value => ({
                exact: movinaClassicNormalize(value),
                base: normalizeSeriesBaseName(value)
            }))
            .filter(value => value.exact);

        const exactNameMatches = names.some(
            value => value.exact === expectedName
        );

        const seasonBaseMatches = names.some(
            value => value.base === expectedName
        );

        if (!exactNameMatches && !seasonBaseMatches) {
            return false;
        }

        const expectedYear = Number(title?.year) || 0;
        const candidateYear = itemYear(item);

        if (expectedYear && candidateYear) {
            if (Math.abs(expectedYear - candidateYear) > 1) {
                return false;
            }
        }

        return true;
    });

    if (!exactCandidates.length) return null;

    // Ưu tiên tuyệt đối mã IMDb trùng khớp.
    if (title.imdbId) {
        const idMatches = exactCandidates.filter(
            item =>
                movinaClassicItemIMDbId(item) === title.imdbId
        );

        if (idMatches.length === 1) {
            return idMatches[0];
        }

        // Không ghép nếu tên trùng nhưng IMDb ID mâu thuẫn.
        const candidatesWithId = exactCandidates.filter(
            item => movinaClassicItemIMDbId(item)
        );

        if (candidatesWithId.length > 0) {
            return null;
        }
    }

    // Nếu chỉ có một bản ghi tên phù hợp, nhận bản ghi đó.
    if (exactCandidates.length === 1) {
        return exactCandidates[0];
    }

    // Khi có nhiều mùa, ưu tiên Phần 1 nếu năm không phân biệt
    // được duy nhất một bản ghi.
    if (!title.year) {
        const seasonOne = exactCandidates.filter(
            item => getSeasonNumber(item) === 1
        );

        if (seasonOne.length === 1) {
            return seasonOne[0];
        }
    }

    // Nếu có năm IMDb, ưu tiên các bản ghi khớp năm.
    if (title.year) {
        const sameYear = exactCandidates.filter(item => {
            const year = itemYear(item);

            return year &&
                Math.abs(year - Number(title.year)) <= 1;
        });

        if (sameYear.length === 1) {
            return sameYear[0];
        }

        if (sameYear.length > 1) {
            const seasonOne = sameYear.filter(
                item => getSeasonNumber(item) === 1
            );

            if (seasonOne.length === 1) {
                return seasonOne[0];
            }
        }
    }

    // Không tự chọn ngẫu nhiên khi vẫn còn nhiều bản ghi mơ hồ.
    return null;
}


async function movinaClassicSearchPhimAPI(title, type) {
    const cacheKey = [
        type,
        movinaClassicNormalize(title.title),
        title.imdbId || "",
        title.year || 0
    ].join("|");

    const TTL = 12 * 60 * 60 * 1000;
    const cached = MOVINA_CLASSIC_SEARCH_CACHE.get(cacheKey);

    if (cached && Date.now() - cached.time < TTL) {
        return cached.item;
    }

    try {
        const response = await movinaPhimApiGet(
    "https://phimapi.com/v1/api/tim-kiem",
    {
        params: {
            keyword: title.title,
            page: 1,
            limit: 20,
            filterType: type === "series" ? "series" : "single"
        },
        timeout: 4000,
        headers: {
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json"
        }
    }
);

        const items =
            response.data?.data?.items ||
            response.data?.items ||
            [];

        let match = movinaClassicFindExactMatch(
            title,
            Array.isArray(items) ? items : []
        );

        /*
         * PHIM LẺ:
         * Nếu tìm bằng tên không thành công, thử tra cứu
         * bằng IMDb ID. Chỉ dùng kết quả nếu không phát hiện
         * IMDb ID mâu thuẫn hoặc loại nội dung không phù hợp.
         */
        if (
            !match &&
            type === "movie" &&
            title.imdbId
        ) {
            try {
                const imdbResponse = await movinaPhimApiGet(
    "https://phimapi.com/imdb/title/" +
        encodeURIComponent(title.imdbId),
    {
        timeout: 2200,
        headers: {
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json"
        }
    }
);

                const data = imdbResponse.data || {};

                const candidate =
                    data?.movie ||
                    data?.data?.movie ||
                    data?.data?.item ||
                    data?.item ||
                    null;

                if (
                    candidate &&
                    typeof candidate === "object" &&
                    candidate.slug &&
                    candidate.name
                ) {
                    const candidateIMDbId =
                        movinaClassicItemIMDbId(candidate);

                    const candidateType = String(
                        candidate?.type ||
                        candidate?.tmdb?.type ||
                        ""
                    ).trim().toLowerCase();

                    const isExplicitSeries = [
                        "series",
                        "tv",
                        "tvshow",
                        "tvshows"
                    ].includes(candidateType);

                    const expectedYear =
                        Number(title.year) || 0;

                    const actualYear = itemYear(candidate);

                    const yearMatches =
                        !expectedYear ||
                        !actualYear ||
                        Math.abs(expectedYear - actualYear) <= 1;

                    const idMatches =
                        !candidateIMDbId ||
                        candidateIMDbId === title.imdbId;

                    if (
                        !isExplicitSeries &&
                        idMatches &&
                        yearMatches
                    ) {
                        match = {
                            ...candidate,
                            __catalogType: "movie"
                        };
                    }
                }
            } catch (error) {
                console.warn(
                    "[MOVINA CLASSIC MOVIE IMDb FALLBACK]",
                    JSON.stringify({
                        title: title.title,
                        imdbId: title.imdbId,
                        error: error?.message || String(error)
                    })
                );
            }
        }

        MOVINA_CLASSIC_SEARCH_CACHE.set(cacheKey, {
            time: Date.now(),
            item: match || null
        });

        return match || null;

    } catch (error) {
        console.warn(
            "[MOVINA CLASSIC PHIMAPI SEARCH ERROR]",
            JSON.stringify({
                type,
                title: title.title,
                status: error?.response?.status || 0,
                error: error?.message || String(error)
            })
        );

        // Không cache lỗi mạng; cho phép thử lại ở yêu cầu sau.
        return null;
    }
}

async function movinaFetchClassicCatalogUncached(type) {
    const rankedTitles =
        await movinaClassicGetRankedTitles(type);

    if (!rankedTitles.length) {
        return [];
    }

    const TARGET = CATALOG_TARGET;
    const matchedByKey = new Map();
    const matchedRanks = new Set();
   
function addMatch(ranked, sourceItem) {
    if (!ranked || !sourceItem) return;

    const key = catalogKey(sourceItem);

    if (!key) return;

    matchedRanks.add(ranked.rank);

    if (matchedByKey.has(key)) return;

    matchedByKey.set(key, {
        ...sourceItem,
        __catalogType: type,
        __movinaClassicRank: ranked.rank,
        __movinaClassicSource: "ranked-json",
        __movinaClassicImdbId:
            ranked.imdbId ||
            movinaClassicItemIMDbId(sourceItem) ||
            "",
        __movinaIMDbRating: ranked.rating || 0
    });
}

    /*
     * PHIM BỘ:
     * Ghép kho danh sách trước, sau đó tìm trực tiếp
     * những phim IMDb còn thiếu.
     */
 


if (type === "series") {
    /*
     * CLASSIC SERIES — SEARCH FIRST
     * - Tăng từ 2 lên 3 worker.
     * - Đếm kết quả duy nhất ngay trong quá trình tìm.
     * - Giữ nguyên thứ hạng IMDb.
     * - Không tiếp tục cấp việc khi đủ 50 phim.
     */

    const SEARCH_CONCURRENCY = 5;
    const MAX_SEARCHES = Math.min(
        100,
        rankedTitles.length
    );

    let searched = 0;
    let matchedSearches = 0;
    let searchErrors = 0;
    let nextIndex = 0;

    const searchResults =
        new Array(MAX_SEARCHES);

    const matchedSearchKeys = new Set();

    async function classicSeriesSearchWorker() {
        while (
            nextIndex < MAX_SEARCHES &&
            matchedSearchKeys.size < TARGET
        ) {
            const index = nextIndex++;
            const ranked = rankedTitles[index];

            if (!ranked || !ranked.title) {
                searchResults[index] = null;
                continue;
            }

            searched++;

            try {
                const item =
                    await movinaClassicSearchPhimAPI(
                        ranked,
                        "series"
                    );

                searchResults[index] = {
                    ranked,
                    item
                };

                if (item) {
                    matchedSearches++;

                    const key = catalogKey(item);

                    if (key) {
                        matchedSearchKeys.add(key);
                    }
                }
            } catch (error) {
                searchErrors++;

                searchResults[index] = {
                    ranked,
                    item: null
                };
            }
        }
    }

    await Promise.all(
        Array.from(
            {
                length: Math.min(
                    SEARCH_CONCURRENCY,
                    MAX_SEARCHES
                )
            },
            () => classicSeriesSearchWorker()
        )
    );

    // Chỉ thêm kết quả theo thứ hạng IMDb gốc.
    for (const result of searchResults) {
        if (
            !result ||
            !result.ranked ||
            !result.item
        ) {
            continue;
        }

        addMatch(
            result.ranked,
            result.item
        );
    }

    const result =
        Array.from(matchedByKey.values())
            .sort((a, b) =>
                (a.__movinaClassicRank || 9999) -
                (b.__movinaClassicRank || 9999)
            )
            .slice(0, TARGET);

    console.log(
        "[MOVINA CLASSIC SERIES SEARCH-FIRST SUMMARY]",
        JSON.stringify({
            rankedTitles: rankedTitles.length,
            searchLimit: MAX_SEARCHES,
            searched,
            searchConcurrency: SEARCH_CONCURRENCY,
            matchedSearches,
            uniqueMatched: matchedSearchKeys.size,
            searchErrors,
            returned: result.length,
            target: TARGET,
            directIMDbLookups: 0,
            strategy: "search-first",
            note: "Results sorted by original IMDb rank"
        })
    );

    return result;
}

    
    /*
     * PHIM LẺ:
     * Worker pool chạy liên tục thay vì chờ từng đợt 32 phim.
     * Giữ nguyên đối chiếu tên/năm và thứ hạng IMDb.
     */
    const CONCURRENCY = 5;
    let searched = 0;
    let nextIndex = 0;

    async function classicMovieSearchWorker() {
        while (
            nextIndex < rankedTitles.length &&
            matchedByKey.size < TARGET
        ) {
            const index = nextIndex++;
            const ranked = rankedTitles[index];

            if (!ranked) {
                continue;
            }

            searched++;

            try {
                const item = await movinaClassicSearchPhimAPI(
                    ranked,
                    "movie"
                );

                
                // Giữ mọi kết quả đã được worker cấp việc.
                // Cuối hàm sẽ sắp xếp theo hạng IMDb và cắt 50 phim,
                // không loại phim hạng cao chỉ vì worker khác chạy nhanh hơn.
                if (item) {
                    addMatch(ranked, item);
                }

            } catch (error) {
                console.warn(
                    "[MOVINA CLASSIC MOVIE WORKER ERROR]",
                    ranked.title || ranked.imdbId || index,
                    error?.message || error
                );
            }
        }
    }

    const workerCount = Math.min(
        CONCURRENCY,
        rankedTitles.length
    );

    await Promise.all(
        Array.from(
            { length: workerCount },
            () => classicMovieSearchWorker()
        )
    );

    const result = Array.from(matchedByKey.values())
        .sort((a, b) =>
            (a.__movinaClassicRank || 9999) -
            (b.__movinaClassicRank || 9999)
        )
        .slice(0, TARGET);

    console.log(
        "[MOVINA CLASSIC MATCH SUMMARY]",
        JSON.stringify({
            type,
            rankedTitles: rankedTitles.length,
            searched,
            concurrency: CONCURRENCY,
            matchedPhimAPI: matchedByKey.size,
            returned: result.length,
            target: TARGET
        })
    );

    return result;
}

/* ============================================================
   [STREMIO-012.05] [PROVIDERS: MOVINA]
   CLASSIC CATALOG RESULT CACHE
   - Cache riêng movie / series.
   - Giữ nguyên thứ hạng và kết quả ghép.
   - Chống nhiều request cùng lúc dò lại Top IMDb.
   ============================================================ */

const MOVINA_CLASSIC_CATALOG_CACHE = new Map();
const MOVINA_CLASSIC_CATALOG_INFLIGHT = new Map();

const MOVINA_CLASSIC_CATALOG_TTL = 6 * 60 * 60 * 1000;

async function movinaFetchClassicCatalog(type) {
    const normalizedType =
        type === "series" ? "series" : "movie";

    const now = Date.now();
    const cached =
        MOVINA_CLASSIC_CATALOG_CACHE.get(normalizedType);

    if (cached && cached.expiresAt > now) {
        console.log(
            "[MOVINA CLASSIC CATALOG CACHE] HIT:",
            normalizedType,
            "| Items:",
            cached.items.length
        );

        return cached.items.map(item => ({ ...item }));
    }

    if (cached) {
        MOVINA_CLASSIC_CATALOG_CACHE.delete(normalizedType);
    }

    const running =
        MOVINA_CLASSIC_CATALOG_INFLIGHT.get(normalizedType);

    if (running) {
        console.log(
            "[MOVINA CLASSIC CATALOG CACHE] IN-FLIGHT:",
            normalizedType
        );

        const items = await running;
        return items.map(item => ({ ...item }));
    }

    const task = movinaFetchClassicCatalogUncached(
        normalizedType
    );

    MOVINA_CLASSIC_CATALOG_INFLIGHT.set(
        normalizedType,
        task
    );

    try {
        const items = await task;

        if (Array.isArray(items) && items.length > 0) {
            MOVINA_CLASSIC_CATALOG_CACHE.set(
                normalizedType,
                {
                    expiresAt:
                        Date.now() + MOVINA_CLASSIC_CATALOG_TTL,
                    items: items.map(item => ({ ...item }))
                }
            );
        }

        console.log(
            "[MOVINA CLASSIC CATALOG CACHE] STORED:",
            normalizedType,
            "| Items:",
            Array.isArray(items) ? items.length : 0
        );

        return Array.isArray(items) ? items : [];

    } finally {
        if (
            MOVINA_CLASSIC_CATALOG_INFLIGHT.get(normalizedType) === task
        ) {
            MOVINA_CLASSIC_CATALOG_INFLIGHT.delete(normalizedType);
        }
    }
}

// Ngày Việt Nam: thay đổi danh sách theo ngày.
function movinaTrendingDaySeed() {
    return new Date(
        Date.now() + 7 * 60 * 60 * 1000
    ).toISOString().slice(0, 10);
}

