    // ============================================================
    // [LIVE-001.05] [PROVIDERS: IPTV ALL] IPTV ALL M3U PARSER
    // ============================================================

function vmtTvParseM3U(text) {

    const lines =
        String(text || "")
            .split(/\r?\n/);

    const channels = [];

    let current = null;

    for (
        let i = 0;
        i < lines.length;
        i++
    ) {

        const line =
            String(lines[i] || "")
                .trim();

        if (!line) {
            continue;
        }


        // ----------------------------------------------------
        // EXTINF
        // ----------------------------------------------------

        if (
            line.indexOf("#EXTINF:") === 0
        ) {

            const commaIndex =
                line.lastIndexOf(",");

            const info =
                commaIndex >= 0
                    ? line.substring(
                        0,
                        commaIndex
                    )
                    : line;

            const name =
                commaIndex >= 0
                    ? line.substring(
                        commaIndex + 1
                    ).trim()
                    : "";


            const groupMatch =
                info.match(
                    /group-title="([^"]*)"/i
                );

            const logoMatch =
                info.match(
                    /tvg-logo="([^"]*)"/i
                );

            const tvgIdMatch =
                info.match(
                    /tvg-id="([^"]*)"/i
                );


            current = {

                group:
                    groupMatch
                        ? groupMatch[1]
                        : "",

                logo:
                    logoMatch
                        ? logoMatch[1]
                        : "",

                tvgId:
                    tvgIdMatch
                        ? tvgIdMatch[1]
                        : "",

                name,

                index:
                    channels.length,

                url: "",

                userAgent: ""
            };

            continue;
        }


        // ----------------------------------------------------
        // VLC USER-AGENT
        // ----------------------------------------------------

        if (
            line.indexOf(
                "#EXTVLCOPT:http-user-agent="
            ) === 0
        ) {

            if (current) {

                current.userAgent =
                    line.substring(
                        "#EXTVLCOPT:http-user-agent="
                            .length
                    ).trim();
            }

            continue;
        }


        // ----------------------------------------------------
        // IGNORE OTHER DIRECTIVES
        // ----------------------------------------------------

        if (
            line.charAt(0) === "#"
        ) {

            continue;
        }


        // ----------------------------------------------------
        // STREAM URL
        // ----------------------------------------------------

        if (
            line.indexOf("http") === 0 ||
            line.indexOf("//") === 0
        ) {

            if (current) {

                current.url =
                    line.indexOf("//") === 0
                        ? "https:" + line
                        : line;

                channels.push(current);

                current = null;
            }
        }
    }

    return channels;
}


    // ============================================================
    // [LIVE-001.06] [PROVIDERS: IPTV ALL] IPTV ALL CHANNEL ID
    // ============================================================

function vmtTvMakeChannelId(channel) {

    if (
        channel &&
        channel.tvgId
    ) {

        return channel.tvgId;
    }

    return (
        (channel?.group || "unknown") +
        "::" +
        (channel?.name || "") +
        "::" +
        (channel?.index ?? 0)
    );
}



function vmtTvFindChannelById(
    channels,
    channelId
) {
    if (!Array.isArray(channels)) {
        return null;
    }

    const id = String(channelId || "").trim();

    if (!id) {
        return null;
    }

    // 1. Giữ nguyên cơ chế tìm ID chính xác.
    const exact = channels.find(
        channel =>
            vmtTvMakeChannelId(channel) === id
    );

    if (exact) {
        return exact;
    }

    // 2. Fallback cho ID dạng group::name::index.
    const parts = id.split("::");

    if (parts.length >= 3) {
        const expectedIndex = Number(parts[parts.length - 1]);
        const expectedName = parts[parts.length - 2];
        const expectedGroup = parts.slice(0, -2).join("::");

        // Tìm theo cả nhóm và tên trước, không phụ thuộc index.
        const sameGroupAndName = channels.filter(
            channel =>
                String(channel.group || "").trim() === expectedGroup &&
                String(channel.name || "").trim() === expectedName
        );

        if (sameGroupAndName.length === 1) {
            return sameGroupAndName[0];
        }

        // Nếu có nhiều kênh trùng tên trong cùng nhóm,
        // ưu tiên index nếu index đó vẫn còn chính xác.
        if (
            Number.isInteger(expectedIndex) &&
            expectedIndex >= 0
        ) {
            const byIndex = channels[expectedIndex];

            if (
                byIndex &&
                String(byIndex.group || "").trim() === expectedGroup &&
                String(byIndex.name || "").trim() === expectedName
            ) {
                return byIndex;
            }
        }

        // Không chọn tùy tiện nếu có nhiều kết quả trùng.
        if (sameGroupAndName.length > 1) {
            console.log(
                "[VMTTV] Ambiguous channel ID:",
                id,
                "| Matches:",
                sameGroupAndName.length
            );

            return null;
        }
    }

    // 3. Không tự chọn kênh chỉ vì trùng tên,
    // tránh phát nhầm một kênh khác.
    return null;
}



    // ============================================================
    // [LIVE-001.07] [PROVIDERS: IPTV ALL] IPTV ALL LIST RESPONSE
    // ============================================================

function vmtTvParseListResponse(
    apiResponseJson,
    apiUrl
) {

    const channels =
        vmtTvParseM3U(
            apiResponseJson
        );


    let filtered =
        channels;


    // --------------------------------------------------------
    // CATEGORY FILTER
    // --------------------------------------------------------

    try {

        const parsedUrl =
            new URL(apiUrl);

        const categorySlug =
            parsedUrl.searchParams.get("cat");

        if (
            categorySlug &&
            VMTTV_CATEGORY_MAP[categorySlug]
        ) {

            const categoryName =
                VMTTV_CATEGORY_MAP[
                    categorySlug
                ];

            filtered =
                channels.filter(channel =>
                    String(
                        channel.group || ""
                    ).trim() ===
                    categoryName
                );
        }

    } catch (e) {

        console.log(
            "[VMTTV] CATEGORY PARSE ERROR:",
            e?.message || e
        );
    }


    // --------------------------------------------------------
    // SEARCH FILTER
    // --------------------------------------------------------

    try {

        const parsedUrl =
            new URL(apiUrl);

        const search =
            String(
                parsedUrl.searchParams.get("search") ||
                ""
            )
            .trim()
            .toLowerCase();

        if (search) {

            filtered =
                filtered.filter(channel =>
                    String(
                        channel.name || ""
                    )
                    .toLowerCase()
                    .includes(search)
                );
        }

    } catch (e) {

        console.log(
            "[VMTTV] SEARCH PARSE ERROR:",
            e?.message || e
        );
    }


    return filtered.map(channel => ({

        id:
            vmtTvMakeChannelId(
                channel
            ),

        title:
            channel.name,

        posterUrl:
            channel.logo || "",

        backdropUrl:
            channel.logo || "",

        year: 0,

        quality: "LIVE",

        episode_current:
            channel.group || "Live",

        lang:
            channel.group || ""
    }));
}


    // ============================================================
    // [LIVE-001.08] [PROVIDERS: IPTV ALL] IPTV ALL SEARCH RESPONSE
    // ============================================================

function vmtTvParseSearchResponse(
    apiResponseJson,
    apiUrl
) {

    return vmtTvParseListResponse(
        apiResponseJson,
        apiUrl
    );
}


    // ============================================================
    // [LIVE-001.09] [PROVIDERS: IPTV ALL] IPTV ALL DETAIL RESPONSE
    // ============================================================

function vmtTvParseMovieDetail(
    apiResponseJson,
    apiUrl
) {

    const channels =
        vmtTvParseM3U(
            apiResponseJson
        );


    let channelId = "";


    try {

        const parsedUrl =
            new URL(apiUrl);

        channelId =
            parsedUrl.searchParams.get("id") ||
            "";

    } catch (e) {

        console.log(
            "[VMTTV] DETAIL URL ERROR:",
            e?.message || e
        );
    }


    let channel =
        vmtTvFindChannelById(
            channels,
            channelId
        );


    // --------------------------------------------------------
    // FALLBACK BY INDEX
    // --------------------------------------------------------

    if (!channel && channelId) {

        const parts =
            channelId.split("::");

        const last =
            parts[parts.length - 1];

        const index =
            Number(last);

        if (
            Number.isInteger(index) &&
            channels[index]
        ) {

            channel =
                channels[index];
        }
    }


    // --------------------------------------------------------
    // FALLBACK BY CHANNEL NAME
    // --------------------------------------------------------

    if (!channel && channelId) {

        const parts =
            channelId.split("::");

        if (parts.length >= 2) {

            const name =
                parts[
                    parts.length - 2
                ];

            channel =
                channels.find(item =>
                    String(
                        item.name || ""
                    ) === name
                );
        }
    }


    if (!channel) {

        return null;
    }


    let episodeId =
        channel.url || "";


    if (
        channel.userAgent
    ) {

        episodeId +=
            "|ua=" +
            encodeURIComponent(
                channel.userAgent
            );
    }


    return {

        title:
            channel.name,

        posterUrl:
            channel.logo || "",

        backdropUrl:
            channel.logo || "",

        description:
            "LIVE - " +
            (channel.group || "VMT TV"),

        year: 0,

        quality: "LIVE",

        episode_current: "Live",

        lang:
            channel.group || "",

        category:
            channel.group || "",

        country: "",

        director:
            "VMT TV",

        servers: [

            {

                name:
                    channel.group ||
                    "Live Source",

                episodes: [

                    {

                        id:
                            episodeId,

                        title:
                            channel.name,

                        name:
                            channel.name
                    }

                ]
            }

        ]
    };
}


    // ============================================================
    // [LIVE-001.10] [PROVIDERS: IPTV ALL] IPTV ALL STREAM DETAIL
    // ============================================================

function vmtTvParseDetailResponse(
    apiResponseJson,
    apiUrl
) {

    const raw =
        String(
            apiUrl || ""
        ).trim();

    if (!raw) {
        return null;
    }


    let streamUrl =
        raw;

    let userAgent =
        "";


    // --------------------------------------------------------
    // EXTRACT |ua=
    // --------------------------------------------------------

    const uaIndex =
        raw.indexOf("|ua=");

    if (uaIndex >= 0) {

        streamUrl =
            raw.substring(
                0,
                uaIndex
            );

        userAgent =
            decodeURIComponent(
                raw.substring(
                    uaIndex + 4
                )
            );
    }


    if (!userAgent) {

        userAgent =
            "Mozilla/5.0 (Linux; Android 10; K) " +
            "AppleWebKit/537.36 " +
            "(KHTML, like Gecko) " +
            "Chrome/131.0.0.0 Mobile Safari/537.36";
    }


    return {

        url:
            streamUrl,

        headers: {

            "User-Agent":
                userAgent
        },

        subtitles: [],

        type: "LIVE"
    };
}


