// ============================================================
// [STREMIO-082] [PROVIDERS: IPTV ALL] IPTV ALL STREAM ADAPTER
// ============================================================
//
// Adapter riêng của IPTV ALL.
//
// Không chứa logic tìm provider.
// Không chứa logic registry.
//
// Nhiệm vụ:
//
//   IPTV ALL channel
//        ↓
//   Normalized LIVE Stream
//        ↓
//   Stremio TV stream
//
// ============================================================


async function fetchVmtTvChannels() {

    try {

        const response =
            await axios.get(
                VMTTV_M3U_URL,
                {
                    timeout: 15000,

                    headers: {
                        "User-Agent":
                            "Mozilla/5.0",

                        "Accept":
                            "*/*"
                    }
                }
            );

        return vmtTvParseM3U(
            response.data
        );

    } catch (e) {

        console.log(
            "[VMTTV STREMIO] M3U ERROR:",
            e?.response?.status ||
            e?.message ||
            e
        );

        return [];
    }
}


/* ============================================================
   [LIVE-002] [PROVIDERS: COBAN] CO BAN TV PLAYLIST ADAPTER
   ============================================================ */

const COBAN_M3U_URL =
    "https://rg.com.vn/coban";

// [LIVE-002.01] [PROVIDERS: COBAN] FETCH M3U PLAYLIST

async function fetchCobanChannels() {
    const TAG = "[COBAN]";
    const isM3U = value =>
        /#EXTINF\s*:/i.test(
            String(value || "").replace(/^\uFEFF/, "")
        );

    const parsePlaylist = body => {
        const text = String(body || "").replace(/^\uFEFF/, "");
        if (!isM3U(text)) return null;

        const channels = vmtTvParseM3U(text);
        return Array.isArray(channels) && channels.length
            ? channels
            : null;
    };

    const getText = async url => {
        const response = await axios.get(url, {
            timeout: 25000,
            responseType: "text",
            maxRedirects: 5,
            headers: {
                "User-Agent": "Mozilla/5.0",
                "Accept": "*/*"
            }
        });

        return {
            body: response.data,
            finalUrl:
                response.request?.res?.responseUrl ||
                response.config?.url ||
                url,
            status: response.status
        };
    };

    try {
        // Thử URL gốc trước để tự nhận chuyển hướng mới nhất.
        const first = await getText(COBAN_M3U_URL);
        let channels = parsePlaylist(first.body);

        if (channels) {
            console.log(TAG, "Channels loaded:", channels.length);
            return channels;
        }

        console.warn(TAG, "URL gốc không trả M3U; thử link tải Dropbox.");

        // Dropbox có thể trả trang xem trước thay vì nội dung playlist.
        const candidates = [];

        try {
            const redirected = new URL(first.finalUrl);
            redirected.searchParams.set("dl", "1");
            candidates.push(redirected.toString());

            if (redirected.hostname.includes("dropboxusercontent.com")) {
                const shareUrl = new URL(redirected.toString());
                shareUrl.hostname = "www.dropbox.com";
                shareUrl.searchParams.set("dl", "1");
                candidates.push(shareUrl.toString());
            }
        } catch (_) {
            // Giữ nguyên lỗi dữ liệu bên dưới nếu URL chuyển hướng không hợp lệ.
        }

        for (const url of [...new Set(candidates)]) {
            try {
                const result = await getText(url);
                channels = parsePlaylist(result.body);

                if (channels) {
                    console.log(TAG, "Channels loaded via download URL:", channels.length);
                    return channels;
                }

                console.warn(TAG, "Link vẫn không phải M3U:", {
                    status: result.status,
                    url: result.finalUrl,
                    preview: String(result.body || "").slice(0, 100)
                });
            } catch (error) {
                console.warn(TAG, "Download URL failed:", error?.message || error);
            }
        }

        console.error(TAG, "Không lấy được playlist M3U hợp lệ từ URL nguồn.");
        return [];
    } catch (error) {
        console.error(
            TAG,
            "M3U FETCH ERROR:",
            error?.response?.status || error?.message || error
        );
        return [];
    }
}

// [LIVE-002.02] [PROVIDERS: COBAN] CHANNEL ID HELPERS
function makeCobanStremioId(channelId) {
    return (
        "coban:" +
        encodeURIComponent(String(channelId || ""))
    );
}

function decodeCobanStremioId(id) {
    const raw = String(id || "").trim();

    if (!raw.startsWith("coban:")) {
        return "";
    }

    try {
        return decodeURIComponent(
            raw.substring("coban:".length)
        );
    } catch (_) {
        return raw.substring("coban:".length);
    }
}

// [LIVE-002.03] [PROVIDERS: COBAN] CHANNEL META
function makeCobanCatalogMeta(channel) {
    if (!channel) {
        return null;
    }

    const channelId = vmtTvMakeChannelId(channel);
    const group = String(
        channel.group || "LIVE"
    ).trim();

    return {
        id: makeCobanStremioId(channelId),
        type: "tv",
        name: String(channel.name || "Cơ Bản TV").trim(),
        poster: String(channel.logo || "").trim(),
        posterShape: "square",
        description: "🔴 LIVE • " + group,
        genres: [group, "LIVE TV", "IPTV"],
        releaseInfo: "LIVE",
        behaviorHints: {
            isLive: true
        },
        links: [
            {
                name: "↩️ VỀ DANH SÁCH KÊNH CƠ BẢN",
                category: "catalog",
                url:
                    "stremio:///discover/" +
                    encodeURIComponent(
                        "https://my-strem-addon.vercel.app/manifest.json"
                    ) +
                    "/MOVINA/pa_tv?provider=coban"
            }
        ]
    };
}

// [LIVE-002.04] [PROVIDERS: COBAN] RESOLVE LIVE CHANNEL
async function resolveCobanChannel(channelId) {
    const channels = await fetchCobanChannels();

    const channel = vmtTvFindChannelById(
        channels,
        channelId
    );

    if (!channel || !channel.url) {
        console.log(
            "[COBAN] Channel not found or has no URL:",
            channelId
        );
        return [];
    }

    const normalized = normalizeLiveStream(
        {
            url: channel.url,
            headers: channel.userAgent
                ? { "User-Agent": channel.userAgent }
                : {},
            title: channel.name,
            type: "LIVE"
        },
        "coban"
    );

    return normalized ? [normalized] : [];
}

// ============================================================
// [STREMIO-082.02] [PROVIDERS: IPTV ALL] CHANNEL ID PARSER
// ============================================================
//
// Stremio ID:
//
//     vmttv:<encoded-channel-id>
//
// Ví dụ:
//
//     vmttv:TVB%3A%3ATVB%20Jade%3A%3A12
//
// ============================================================

function makeVmtTvStremioId(channelId) {

    return (
        "vmttv:" +
        encodeURIComponent(
            String(
                channelId || ""
            )
        )
    );
}


function decodeVmtTvStremioId(id) {

    const raw =
        String(id || "")
            .trim();

    if (
        !raw.startsWith("vmttv:")
    ) {
        return "";
    }

    try {

        return decodeURIComponent(
            raw.substring(
                "vmttv:".length
            )
        );

    } catch (e) {

        return raw.substring(
            "vmttv:".length
        );
    }
}


// ============================================================
// [STREMIO-082.03] [PROVIDERS: IPTV ALL] META PREVIEW
// ============================================================

function makeVmtTvCatalogMeta(channel) {

    if (!channel) {
        return null;
    }

    const channelId =
        vmtTvMakeChannelId(
            channel
        );

    const title =
        String(
            channel.name ||
            "VMT TV"
        ).trim();

    const poster =
        String(
            channel.logo ||
            ""
        ).trim();

    const category =
        String(
            channel.group ||
            "LIVE"
        ).trim();

    return {

        id:
            makeVmtTvStremioId(
                channelId
            ),

        type:
            "tv",

        name:
            title,

        poster:
            poster,

        posterShape:
            "square",

        description:
            "🔴 LIVE • " +
            category,

        genres: [
            category
        ],

        releaseInfo:
            "LIVE",

        behaviorHints: {
            isLive: true
        }
    };
}


// ============================================================
// [STREMIO-083] [PROVIDERS: IPTV ALL] IPTV ALL FULL META ADAPTER
// ============================================================

function makeVmtTvMeta(channel) {

    const preview =
        makeVmtTvCatalogMeta(
            channel
        );


    if (!preview) {
        return null;
    }


    return {

        ...preview,


        background:
            channel.logo ||
            "",


        logo:
            channel.logo ||
            "",


        country:
            "",


        language:
            "",


        // ====================================================
        // NAVIGATION
        // ====================================================

        links: [

            ...(Array.isArray(preview.links)
                ? preview.links
                : []),

            {
                name:
                    "↩️ VỀ DANH SÁCH NHÓM",

                category:
                    "catalog",

                url:
                    "stremio:///discover/" +
                    encodeURIComponent(
                        "https://my-strem-addon.vercel.app/manifest.json"
                    ) +
                    "/MOVINA/pa_tv?" +
                    "provider=vmttv"
            }
        ],


        // ====================================================
        // VIDEO PREVIEW
        // ====================================================

        videos: [

            {
                id:
                    preview.id,

                title:
                    channel.name,

                released:
                    new Date().toISOString(),

                thumbnail:
                    channel.logo ||
                    "",

                available:
                    true
            }
        ]
    };
}


// ============================================================
// [STREMIO-084] [PROVIDERS: IPTV ALL] IPTV ALL NORMALIZED STREAM ADAPTER
// ============================================================

async function resolveVmtTvChannel(
    channelId
) {

    const channels =
        await fetchVmtTvChannels();

    const channel =
        vmtTvFindChannelById(
            channels,
            channelId
        );

    if (!channel) {

        console.log(
            "[VMTTV STREMIO] CHANNEL NOT FOUND:",
            channelId
        );

        return [];
    }

    if (!channel.url) {

        console.log(
            "[VMTTV STREMIO] CHANNEL HAS NO URL:",
            channel.name
        );

        return [];
    }

    const rawStream = {

        url:
            channel.url,

        headers:
            channel.userAgent
                ? {
                    "User-Agent":
                        channel.userAgent
                }
                : {},

        title:
            channel.name,

        type:
            "LIVE"
    };


    const normalized =
        normalizeLiveStream(
            rawStream,
            "vmttv"
        );

    if (!normalized) {
        return [];
    }

    return [
        normalized
    ];
}


console.log(
    "[VMTTV STREMIO ADAPTER] READY"
);

    // ============================================================
