    // ============================================================
    // 4. GET
    // ============================================================

    async function get(
        url,
        headers = {}
    ) {

        const controller =
            new AbortController();

        const timer =
            setTimeout(
                () =>
                    controller.abort(),
                timeoutMs
            );

        try {

            return await fetch(
                url,
                {
                    method:
                        "GET",

                    redirect:
                        "follow",

                    signal:
                        controller.signal,

                    headers: {

                        "User-Agent":
                            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131 Safari/537.36",

                        "Accept":
                            "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",

                        ...headers

                    }

                }
            );

        } finally {

            clearTimeout(
                timer
            );

        }

    }

    // ============================================================
    // 5. CRYPTO
    // ============================================================

    function cryptoJSAesDecrypt(
        passphrase,
        encryptedJsonString
    ) {

        const crypto =
            require("crypto");

        const obj =
            JSON.parse(
                encryptedJsonString
            );

        const encrypted =
            Buffer.from(
                obj.ciphertext,
                "base64"
            );

        const salt =
            Buffer.from(
                obj.salt,
                "hex"
            );

        const iv =
            Buffer.from(
                obj.iv,
                "hex"
            );

        const key =
            crypto.pbkdf2Sync(
                Buffer.from(
                    passphrase,
                    "utf8"
                ),
                salt,
                999,
                32,
                "sha512"
            );

        const decipher =
            crypto.createDecipheriv(
                "aes-256-cbc",
                key,
                iv
            );

        return Buffer.concat([
            decipher.update(
                encrypted
            ),
            decipher.final()
        ]).toString(
            "utf8"
        );

    }

    // ============================================================
    // 6. BASE64 URL
    // ============================================================

    function decodeBase64Url(
        value
    ) {

        try {

            let s =
                decodeURIComponent(
                    value || ""
                );

            s =
                s.replace(
                    /-/g,
                    "+"
                )
                .replace(
                    /_/g,
                    "/"
                );

            while (
                s.length % 4 !== 0
            ) {

                s += "=";

            }

            return Buffer.from(
                s,
                "base64"
            ).toString(
                "utf8"
            );

        } catch (e) {

            console.log(
                "[PHIMLONGTIENG] Base64 decode error:",
                e.message
            );

            return null;

        }

    }

    // ============================================================
    // 7. ENCRYPTED JSON
    // ============================================================

    function extractEncryptedJson(
        html
    ) {

        const marker =
            "CryptoJSAesDecrypt('Encrypt', `";

        let pos = 0;

        const candidates = [];

        while (true) {

            const found =
                html.indexOf(
                    marker,
                    pos
                );

            if (found < 0) {
                break;
            }

            const start =
                found +
                marker.length;

            const end =
                html.indexOf(
                    "`",
                    start
                );

            if (
                end > start
            ) {

                const candidate =
                    html.substring(
                        start,
                        end
                    ).trim();

                try {

                    const obj =
                        JSON.parse(
                            candidate
                        );

                    if (
                        obj &&
                        obj.ciphertext &&
                        obj.iv &&
                        obj.salt
                    ) {

                        candidates.push(
                            candidate
                        );

                    }

                } catch (_) {}

            }

            pos =
                start;

        }

        console.log(
            "[PHIMLONGTIENG] Valid encrypted JSON candidates:",
            candidates.length
        );

        if (
            !candidates.length
        ) {

            return null;

        }

        return candidates[
            candidates.length - 1
        ];

    }

    // ============================================================
    // 8. PLAY2
    // ============================================================

    function extractPlay2Streams(
        html,
        baseUrl,
        labelPrefix = "PLAY2"
    ) {

        const found = [];

        const regex =
            /https?:\/\/[^"'<>\\\s]+\/play2\.php\?[^"'<>\\\s]+/gi;

        let m;

        while (
            (m = regex.exec(html)) !== null
        ) {

            let url =
                decodeHtml(
                    m[0]
                );

            url =
                url.replace(
                    /[)"';,]+$/g,
                    ""
                );

            if (
                !found.includes(url)
            ) {

                found.push(
                    url
                );

            }

        }

        console.log(
            `[PHIMLONGTIENG] ${labelPrefix} play2 count:`,
            found.length
        );

        for (
            const play2Url
            of found
        ) {

            try {

                const parsed =
                    new URL(
                        play2Url
                    );

                const hash =
                    parsed.searchParams.get(
                        "hash"
                    );

                if (!hash) {

                    console.log(
                        "[PHIMLONGTIENG] play2 WITHOUT hash:",
                        play2Url
                    );

                    continue;

                }

                const decoded =
                    decodeBase64Url(
                        hash
                    );

                console.log(
                    "[PHIMLONGTIENG] play2 decoded:",
                    decoded
                );

                if (
                    decoded &&
                    /^https?:\/\//i.test(
                        decoded
                    )
                ) {

                    addStream(
                        decoded,
                        `${labelPrefix} - Direct`,
                        baseUrl,
                        labelPrefix
                    );

                }

            } catch (e) {

                console.log(
                    "[PHIMLONGTIENG] play2 parse error:",
                    e.message
                );

            }

        }

        return found;

    }

    // ============================================================
    // 9. DIRECT M3U8
    // ============================================================

    function extractDirectM3U8(
        html,
        baseUrl,
        label = "Direct"
    ) {

        const found = [];

        const patterns = [

            /https?:\/\/[^"'<>\\\s]+\.m3u8(?:\?[^"'<>\\\s]*)?/gi,

            /https?:\\\/\\\/[^"'<>\\\s]+\.m3u8(?:\?[^"'<>\\\s]*)?/gi

        ];

        for (
            const regex
            of patterns
        ) {

            let m;

            while (
                (m = regex.exec(html)) !== null
            ) {

                let url =
                    m[0]
                        .replace(
                            /\\\//g,
                            "/"
                        )
                        .replace(
                            /\\u0026/g,
                            "&"
                        )
                        .replace(
                            /[)"';,]+$/g,
                            ""
                        );

                if (
                    !found.includes(url)
                ) {

                    found.push(
                        url
                    );

                }

            }

        }

        console.log(
            `[PHIMLONGTIENG] ${label} direct M3U8:`,
            found
        );

        for (
            const url
            of found
        ) {

            addStream(
                url,
                `${label} - M3U8`,
                baseUrl,
                label
            );

        }

        return found;

    }

