    // ============================================================
    // 12. SUPPORT CONTEXT HELPERS
    // ============================================================

    function collectObjectStrings(
        value,
        output = []
    ) {

        if (
            value === null ||
            value === undefined
        ) {

            return output;

        }

        if (
            typeof value === "string"
        ) {

            const s =
                value.trim();

            if (s.length >= 2) {

                output.push(
                    s
                );

            }

            return output;

        }

        if (
            typeof value === "number" ||
            typeof value === "boolean"
        ) {

            output.push(
                String(value)
            );

            return output;

        }

        if (
            Array.isArray(value)
        ) {

            for (
                const item
                of value
            ) {

                collectObjectStrings(
                    item,
                    output
                );

            }

            return output;

        }

        if (
            typeof value === "object"
        ) {

            for (
                const [key, item]
                of Object.entries(value)
            ) {

                // URL stream không phải title.
                // Nhưng các field tên phim vẫn được đọc.
                if (
                    /^(url|stream|link|src|proxy|hls)$/i.test(
                        key
                    )
                ) {

                    continue;

                }

                if (
                    typeof item === "string" &&
                    item.length > 500
                ) {

                    continue;

                }

                collectObjectStrings(
                    item,
                    output
                );

            }

        }

        return output;

    }

    function getContextTitles(
        sourceArray
    ) {

        const titles = [];

        if (
            !Array.isArray(
                sourceArray
            )
        ) {

            return titles;

        }

        for (
            const item
            of sourceArray
        ) {

            if (
                !item ||
                typeof item !== "object"
            ) {

                continue;

            }

            const possibleKeys = [

                "title",
                "name",
                "movieName",
                "movie_name",
                "originalName",
                "original_name",
                "showName",
                "show_name",
                "seriesName",
                "series_name",
                "metaName",
                "meta_name"

            ];

            for (
                const key
                of possibleKeys
            ) {

                if (
                    typeof item[key] ===
                    "string"
                ) {

                    const value =
                        item[key].trim();

                    if (
                        value.length >= 2
                    ) {

                        titles.push(
                            value
                        );

                    }

                }

            }

        }

        return Array.from(
            new Set(
                titles
            )
        );

    }

