// ============================================================
// MOVINA TV — GROUP VIDEO DEEP LINK
//
// Khi chọn một nhóm trong trang series của nguồn TV,
// mở trang chi tiết series của chính nhóm đó.
// ============================================================

if (
    streamType === "series" &&
    (
        rawId.startsWith("vmttv-group:") ||
        rawId.startsWith("coban-group:") ||
        rawId.startsWith("sportsiptv-group:")
    )
) {
    const groupPrefixes = [
        {
            prefix: "vmttv-group:",
            provider: "vmttv"
        },
        {
            prefix: "coban-group:",
            provider: "coban"
        },
        {
            prefix: "sportsiptv-group:",
            provider: "sportsiptv"
        }
    ];

    const matched = groupPrefixes.find(
        item => rawId.startsWith(item.prefix)
    );

    if (!matched) {
        return { streams: [] };
    }

    let groupName = "";

    try {
        groupName = decodeURIComponent(
            rawId.substring(matched.prefix.length)
        ).trim();
    } catch (_) {
        groupName = rawId
            .substring(matched.prefix.length)
            .trim();
    }

    if (!groupName) {
        return { streams: [] };
    }

    // rawId đã có phần tên nhóm được encodeURIComponent
    // khi tạo ID nhóm. Không mã hóa toàn bộ ID lần nữa.
const detailUrl =
    "stremio:///detail/series/" +
    rawId;

    console.log("[MOVINA TV GROUP DEEPLINK]", {
        provider: matched.provider,
        group: groupName,
        url: detailUrl
    });

    const webDetailUrl =
        "https://web.stremio.com/#/detail/series/" +
        encodeURIComponent(rawId);

    return {
        streams: [
            {
                name: "📺 Mở nhóm trong Stremio",
                description:
                    "Dùng deep link của ứng dụng Stremio",
                externalUrl: detailUrl
            },
            {
                name: "🌐 Mở nhóm bằng Stremio Web",
                description:
                    "Phương án thay thế cho Desktop và điện thoại",
                externalUrl: webDetailUrl
            }
        ]
    };

}

