// =====================================================
// NORMALIZE TITLE
// =====================================================

function normalizeTitle(
    value
) {

    return String(
        value ||
        ""
    )
        .normalize("NFD")
        .replace(
            /[\\\\u0300-\\\\u036f]/g,
            ""
        )
        .toLowerCase()
        .replace(
            /[^a-z0-9]+/g,
            " "
        )
        .replace(
            /\\\\s+/g,
            " "
        )
        .trim();

}


// =====================================================
// SCORE NGUONC SEARCH RESULT
// =====================================================
// TITLE = tiêu chí chính.
// YEAR  = tiêu chí ưu tiên, không phải điều kiện bắt buộc.
// =====================================================

function scoreMovie(
    item
) {

    const target =
        normalizeTitle(
            MOVIE_TITLE
        );

    const name =
        normalizeTitle(
            item?.name
        );

    const origin =
        normalizeTitle(
            item?.origin_name ||
            item?.original_name
        );

    const itemYear =
        Number(
            item?.year ||
            item?.release_year ||
            item?.releaseYear ||
            0
        );

    const rawName =
        String(
            item?.name ||
            ""
        ).trim();

    let score = 0;

    // =================================================
    // TITLE MATCH
    // =================================================

    if (name === target) {
        score += 1000;
    }

    if (origin === target) {
        score += 1000;
    }

    if (
        name.includes(target) &&
        target.length >= 4
    ) {
        score += 300;
    }

    if (
        target.includes(name) &&
        name.length >= 4
    ) {
        score += 250;
    }

    if (
        origin.includes(target) &&
        target.length >= 4
    ) {
        score += 300;
    }

    if (
        target.includes(origin) &&
        origin.length >= 4
    ) {
        score += 250;
    }

    // =================================================
    // YEAR
    // =================================================
    // Đúng năm  → cộng điểm rất cao.
    // Sai năm   → chỉ giảm nhẹ.
    // Không có năm → không phạt.
    //
    // Như vậy:
    // - Có bản đúng năm → ưu tiên bản đó.
    // - Không có bản đúng năm → vẫn chọn được phim.
    // =================================================

    if (MOVIE_YEAR > 0) {

        if (itemYear === MOVIE_YEAR) {

            score += 5000;

        } else if (itemYear > 0) {

            score -= 500;

        }

        // -------------------------------------------------
        // Kiểm tra năm nằm trong tên phim
        // Ví dụ:
        // Tây Du Ký Phần 1 (1996)
        // -------------------------------------------------

        const yearMatch =
            rawName.match(
                /((19|20)[0-9]{2})/
            );

        if (yearMatch) {

            const nameYear =
                Number(
                    yearMatch[0].replace(
                        /[^0-9]/g,
                        ""
                    )
                );

            console.log(
                "[NGUONC CLIENT] NAME YEAR:",
                rawName,
                "=>",
                nameYear
            );

            if (nameYear === MOVIE_YEAR) {

                score += 7000;

            } else {

                score -= 500;

            }
        }
    }

    return score;
}


